/* ==========================================================================
   Question bank — AI driven Perception, Learning and Mapping for Drones
   s:"A" = weekly assignment question (transcribed from your graded screenshots)
   s:"P" = practice question written for this site
   a: indices of correct options (more than one = multiple-select question)
   k: official | submitted | worked | mine  (see ai.js)
   ========================================================================== */
window.QB = [];
(function () {
  "use strict";
  function A(w, n, q, o, a, e, x) { var r = { id: "a" + w + "-" + n, w: w, s: "A", n: n, q: q, o: o, a: a, e: e, k: "official" }; if (x) for (var k in x) r[k] = x[k]; QB.push(r); }
  var pc = {};
  function P(w, q, o, a, e, x) { pc[w] = (pc[w] || 0) + 1; var r = { id: "p" + w + "-" + pc[w], w: w, s: "P", n: pc[w], q: q, o: o, a: a, e: e }; if (x) for (var k in x) r[k] = x[k]; QB.push(r); }
  window.QB_A = A; window.QB_P = P;

  /* ======================= WEEK 1 — assignments ======================= */
  A(1, 1, "Suppose you have a set of vectors {v<sub>1</sub>, v<sub>2</sub>, …, v<sub>k</sub>} ∈ ℝ<sup>n</sup>. If this set is known to be <b>linearly independent</b>, what can be definitively concluded about the linear system Xw = 0, where X is a matrix with these vectors as its columns and w is a vector of weights?",
    ["The system has infinitely many solutions because the vectors span the space", "The only solution to the system is the trivial solution w = 0", "The columns of X span all of ℝ<sup>n</sup>, guaranteeing a solution for any target vector", "The matrix X must be square and invertible"], [1],
    "Xw = w<sub>1</sub>v<sub>1</sub> + … + w<sub>k</sub>v<sub>k</sub>. <i>Linear independence is defined</i> as: this combination equals 0 only when every w<sub>i</sub> = 0. Independence does not mean the vectors span ℝ<sup>n</sup> (k may be smaller than n), and X need not be square.");
  A(1, 2, "If the list of vectors {v<sub>1</sub>, v<sub>2</sub>, …, v<sub>k</sub>} is linearly dependent in some vector space V, and v<sub>1</sub> ≠ 0, then",
    ["there exists an index i ∈ 2,…,k such that v<sub>i</sub> ∈ span(v<sub>1</sub>, …, v<sub>i−1</sub>, v<sub>i+1</sub>, …, v<sub>k</sub>)", "If v<sub>i</sub> is removed, the span of the list remains unchanged", "there are n basis vectors of vector space V", "there are i basis vectors of vector space V, i ≤ n"], [0, 1],
    "This is the <b>Linear Dependence Lemma</b>: in a dependent list some vector (other than the first, non-zero one) is a combination of the others, so it is redundant — deleting it leaves the span unchanged. Nothing in the statement tells us the dimension of V.");
  A(1, 3, "Which of the following statements correctly captures the relationship between Artificial Intelligence (AI), Machine Learning (ML), and Deep Learning (DL)?",
    ["AI, ML, and DL are three independent, non-overlapping fields that solve different classes of problems", "ML is a subset of DL, and DL is a subset of AI. DL is the broadest field, AI the narrowest", "AI is the broadest field encompassing systems that mimic intelligent behavior. ML is a subset of AI that learns patterns from data instead of being explicitly programmed. DL is a subset of ML that uses multi-layered neural networks to learn hierarchical representations.", "AI refers exclusively to rule-based expert systems, while ML and DL refer to any system that uses a neural network architecture"], [2],
    "Nested circles: <b>DL ⊂ ML ⊂ AI</b>. Rule-based expert systems are AI but not ML; decision trees are ML but not DL.");
  A(1, 4, "Which of the following best captures why standard object detectors (trained primarily on ground-level datasets like COCO) tend to underperform when applied directly to aerial/UAV imagery?",
    ["Aerial imagery contains fewer object categories overall, so detectors overfit to a narrow label space.", "Aerial images are typically lower resolution than ground-level images, making all objects equally hard to detect regardless of size.", "The top-down viewpoint causes objects to appear small, densely packed, and at arbitrary orientations, with large scale variation between near and distant objects, conditions ground-level datasets rarely represent.", "Aerial detectors fail mainly because of insufficient GPU memory during inference, not because of any fundamental data or modeling mismatch."], [2],
    "The core issue is a <b>data-distribution mismatch</b>: small objects, dense packing, arbitrary rotation and big scale variation from altitude/oblique views. The other options blame label count, resolution or hardware.");
  A(1, 5, "ImageNet-style datasets (and the models trained on them) became hugely successful largely because they contain images where the object of interest is usually large, centered, upright, and photographed from a natural eye-level viewpoint. What factors may contribute to the performance gap between models trained solely on ImageNet and their performance on satellite or drone imagery?",
    ["Because ImageNet images are in color while aerial images are always grayscale, so the model can't process them correctly", "Because ImageNet has far more classes than any aerial dataset, so the model simply hasn't seen enough categories to generalize", "Because ImageNet's training distribution (large, centered, canonically-oriented, eye-level objects), does not represent the small, densely-packed, arbitrarily-rotated, top-down appearance objects have in aerial imagery.", "Because ImageNet models are too slow computationally to process the larger image sizes typical of aerial photography"], [2],
    "Same idea as the previous question, stated as <b>training distribution ≠ test distribution</b> (domain shift). Aerial images are usually colour, and speed is not the cause of the accuracy gap.");
  A(1, 6, "Traditional feature extraction and deep learning both aim to represent raw data through meaningful features, but they differ fundamentally in how those features are obtained. Which statement best captures this difference?",
    ["Traditional feature extraction and deep learning both require manual, domain-expert-designed features. The only difference is that deep learning uses more layers to combine them", "Traditional feature extraction relies on hand-crafted, domain-expert-designed transformations to reduce raw data into relevant features, which is time-consuming and doesn't scale well. Deep learning instead automatically and progressively learns higher-level, concise feature representations directly from raw data through its layered architecture", "Deep learning eliminates the need for features entirely, operating directly on raw data with no internal representation at all", "Traditional feature extraction is scalable and fast, while deep learning is slower because it must learn features from scratch every time"], [1],
    "Hand-crafted (SIFT, HOG, edges designed by experts) vs <b>learned hierarchical features</b> (edges → parts → objects). Deep networks still have internal representations — they just learn them.");
  A(1, 7, "Supervised learning is often described as \"inductive learning\" where a model learns by emulating a teacher who provides ground-truth answers. Based on this description, which of the following best characterizes the supervised learning process?",
    ["The model is trained on data (x<sub>1</sub>,y<sub>1</sub>),…,(x<sub>n</sub>,y<sub>n</sub>) where the model learns a function f(x,w) to predict y from x. The error between the prediction and the ground-truth y is used to update the model's weights w", "The model is given only inputs (x<sub>1</sub>,…,x<sub>n</sub>) with no corresponding labels, and it must group similar inputs together without any teacher guidance", "The model receives rewards or penalties for actions taken in an environment, and updates its behavior to maximize cumulative reward over time", "The \"teacher\" in this setting refers to a human manually adjusting the model's weights after every single prediction, rather than an automated error-driven update"], [0],
    "Supervised = labelled pairs + error-driven weight update. Option 2 is unsupervised learning, option 3 is reinforcement learning.");
  A(1, 8, "A binary classifier for detecting spam emails is evaluated on a test set of 200 emails: Actual spam → predicted spam 40, predicted not-spam 10. Actual not-spam → predicted spam 30, predicted not-spam 120. Which statement is correct?",
    ["The model has high precision (few false positives relative to predicted positives) but lower recall, since it misses a large fraction of actual spam", "The model has high recall (catches most actual spam) but comparatively lower precision, since a large share of the emails it flags as spam are actually false alarms", "Precision = 40/50 = 0.8 and Recall = 40/70 ≈ 0.57 — the model is better at avoiding false alarms than it is at catching spam", "Since accuracy = (40+120)/200 = 0.8, and accuracy is the most complete measure of performance here, no further metrics are needed to judge this model"], [1],
    "TP = 40, FN = 10, FP = 30, TN = 120. <b>Recall</b> = TP/(TP+FN) = 40/50 = 0.80. <b>Precision</b> = TP/(TP+FP) = 40/70 ≈ 0.57. Option 3 swaps the two formulas — the classic trap. Accuracy hides the false-alarm problem.");

  /* ======================= WEEK 2 — assignments ======================= */
  A(2, 1, "In a vectorized implementation of the Hebbian rule, the weight matrix update is ΔW = η y x<sup>T</sup>. Let η = 0.5, the input column vector x = [1 −1]<sup>T</sup>, and the output y = [2]. What is ΔW?",
    ["[1 −1]", "[1 −1]<sup>T</sup>", "[2 −2]", "x = [−1 1]"], [0],
    "ΔW = 0.5 × 2 × [1 −1] = <b>[1 −1]</b>. y is 1×1 and x<sup>T</sup> is 1×2, so ΔW is a 1×2 <i>row</i> (one row per output neuron), not a column.");
  A(2, 2, "A synapse is updated using the basic Hebbian rule Δw = ηxy. Over N consecutive steps, x = 1 and y = 1 stay constant. If w<sub>0</sub> = 0 and η = 0.2, what is w after N = 10 steps?",
    ["0.2", "1", "2", "0"], [2],
    "Each step adds ηxy = 0.2. After 10 steps w = 10 × 0.2 = <b>2</b>. Note the weight keeps growing linearly — pure Hebbian learning has no bound.");
  A(2, 3, "The Delta rule is derived by taking the negative gradient of E = ½(t − y)<sup>2</sup> with a linear activation y = Σ w<sub>i</sub>x<sub>i</sub>. What is ∂E/∂w<sub>i</sub> (before applying the learning rate)?",
    ["(t − y)", "−(t − y)x<sub>i</sub>", "(t − y)x<sub>i</sub>", "−(t − y)<sup>2</sup>x<sub>i</sub>"], [1],
    "Chain rule: ∂E/∂w<sub>i</sub> = (t − y)·(−1)·∂y/∂w<sub>i</sub> = <b>−(t − y)x<sub>i</sub></b>. The update is the negative of this: Δw<sub>i</sub> = η(t − y)x<sub>i</sub>.");
  A(2, 4, "A network uses the Perceptron Delta rule. η = 0.2, target t = 1.0, prediction y = −1.0, input x<sub>i</sub> = 0.5. What is Δw<sub>i</sub>?",
    ["0.0", "0.1", "0.2", "−0.1"], [2],
    "Δw<sub>i</sub> = η(t − y)x<sub>i</sub> = 0.2 × (1 − (−1)) × 0.5 = 0.2 × 2 × 0.5 = <b>0.2</b>.");
  A(2, 5, "Which activation function produces an output strictly between 0.0 and 1.0 for every finite input x?",
    ["ReLU", "Sigmoid", "Binary step", "Tanh"], [1],
    "σ(x) = 1/(1 + e<sup>−x</sup>) ∈ (0, 1), never touching 0 or 1. ReLU is unbounded above, the step outputs exactly 0 or 1, tanh ∈ (−1, 1).");
  A(2, 6, "The binary step activation is f(x) = 1 if x ≥ 0, 0 if x &lt; 0. What type of output does it produce?",
    ["A continuous output between 0 and 1", "A continuous output between −1 and 1", "A discrete output of either 0 or 1", "An output equal to the input"], [2],
    "Only two possible values → <b>discrete</b>. (It is also not differentiable at 0, which is why gradient descent cannot use it directly.)");
  A(2, 7, "Which of the following statements about activation functions are correct?",
    ["The sigmoid function is continuous and differentiable.", "The binary step function is a discrete activation function.", "ReLU is defined as f(x) = max(0, x)", "Tanh produces outputs only in the set {0, 1}"], [0, 1, 2],
    "Tanh is continuous with range (−1, 1); the set {0, 1} describes the binary step.");
  A(2, 8, "Which Boolean gate produces an output of 1 only when both inputs are 1?",
    ["OR", "XOR", "AND", "NAND"], [2], "AND: 0 0 0 1 (for inputs 00, 01, 10, 11).");
  A(2, 9, "What is the output of the XOR gate when x<sub>1</sub> = 1, x<sub>2</sub> = 1?",
    ["0", "1", "−1", "Undefined"], [0], "XOR = 1 only when the inputs differ: 00→0, 01→1, 10→1, 11→<b>0</b>.");
  A(2, 10, "Which of the following statements about Boolean gates are correct?",
    ["The OR gate produces 1 when at least one input is 1.", "The NAND gate is the complement of the AND gate.", "The XOR gate produces 1 when the inputs are different.", "The AND gate produces 1 when at least one input is 1."], [0, 1, 2],
    "The last statement describes OR, not AND.");
  A(2, 11, "Which Boolean function is not linearly separable?",
    ["AND", "OR", "NAND", "XOR"], [3],
    "XOR's 1-points (0,1),(1,0) sit on one diagonal and 0-points (0,0),(1,1) on the other — no single straight line separates them. Try it in the perceptron demo on the Week 2 page.");
  A(2, 12, "A linear decision boundary in two dimensions can be represented as w<sub>1</sub>x<sub>1</sub> + w<sub>2</sub>x<sub>2</sub> + b = 0. Which statements are correct?",
    ["AND is linearly separable.", "OR is linearly separable.", "XOR is linearly separable.", "A single-layer perceptron can learn linearly separable Boolean functions."], [0, 1, 3],
    "AND: x<sub>1</sub> + x<sub>2</sub> − 1.5 = 0 works; OR: x<sub>1</sub> + x<sub>2</sub> − 0.5 = 0 works. XOR needs a hidden layer.");
  A(2, 13, "Consider the perceptron rule Δw<sub>i</sub> = η(d − y)x<sub>i</sub>. Which statement is correct regarding convergence?",
    ["It is guaranteed to converge only if the training data is linearly separable, in which case the weight updates Δw<sub>i</sub> become progressively large", "It is guaranteed to converge if the training data is linearly separable, in which case the weight updates Δw<sub>i</sub> become progressively smaller.", "It always converges regardless of whether the training data is linearly separable or not.", "It never converges, irrespective of the nature of the training data."], [1],
    "<b>Perceptron convergence theorem</b>: if the classes are linearly separable, the rule reaches a separating line in a finite number of steps; as fewer samples are misclassified, (d − y) is 0 more often, so updates die down. For non-separable data (XOR) it oscillates forever.");
  A(2, 14, "In gradient descent, w(new) = w(old) − η∇E[w], and (d − y)g′(v) is called the local gradient. Which statement correctly describes the role of η and the local gradient?",
    ["η determines the direction of the weight update, while the local gradient determines the step size taken in that direction.", "The local gradient determines the direction and magnitude of the error correction, while η (learning rate) scales the step size of the update, and the weights move in the direction that increases the error E[w]", "The local gradient determines the direction and magnitude of the error correction, while η (learning rate) scales the step size of the update, and the weights move in the direction that decreases the error E[w]", "η and the local gradient together determine only the magnitude of the update, with the direction of descent always being independent of g′(v)."], [2],
    "η is a positive scalar — it can only scale. The gradient gives direction and size; the minus sign makes the weights go <b>downhill</b> (decrease E).");
  A(2, 15, "A neuron uses gradient descent, w<sub>i</sub>(new) = w<sub>i</sub>(old) − η ∂E/∂w<sub>i</sub>, but its activation is the hard limiter y = g(v) = 1 if v &gt; 0, −1 if v ≤ 0 (discontinuous at v = 0). Which update rule could be used to train it correctly?",
    ["Δw<sub>i</sub> = −η(d − y)g′(v)x<sub>i</sub>, using the true gradient as derived above.", "Δw<sub>i</sub> = η(d − y)x<sub>i</sub>, omitting the term g′(v) since it would be discontinuous and may cause issues.", "Δw<sub>i</sub> = ηg′(v)x<sub>i</sub>, dropping the error term (d − y) entirely and relying only on the local gradient.", "Δw<sub>i</sub> = 0, since gradient descent cannot be applied when g′(v) is undefined, and no alternative update rule exists."], [1],
    "g′(v) is 0 everywhere except at 0 where it does not exist, so the true gradient is useless. Dropping it gives the <b>perceptron rule</b>, which still moves weights in the right direction.");
  A(2, 16, "Hebbian: Δw = η(y)x; Delta: Δw = η(d − y)x; Gradient descent: Δw = −η(d − y)g′(v)x. A network is trained with the Hebbian rule on a dataset that includes labels d, but d is never used in the update. Which best explains the consequence and the learning paradigm?",
    ["Since ground-truth labels exist in the dataset, the Hebbian rule is still supervised learning. The presence of labels in the dataset, not their use in the update rule, is what determines the learning paradigm.", "The Hebbian rule reinforces weights purely based on input-output correlation (y·x) regardless of whether y matches d, making it unsupervised. It strengthens connections whenever the neuron fires, even if that firing is \"incorrect\" relative to d; whereas the delta rule and gradient descent explicitly minimize the error (d − y), making them supervised, with gradient descent additionally scaling the correction by the local slope g′(v) of the activation function.", "All three rules are equally supervised, since d is available in the training set for all of them, even though only two rules use it in the formula.", "The Hebbian rule becomes supervised only when g′(v) is incorporated into its update rule, since g′(v) implicitly encodes information about d."], [1],
    "The paradigm is decided by <b>what the update uses</b>. Hebb uses only x and y (correlation) → unsupervised. Delta and gradient descent use the error d − y → supervised.");
  A(2, 17, "Backpropagation has no single well-defined stopping point, so heuristic criteria are used. Which is NOT a valid stopping criterion?",
    ["Stop when ‖∇E(θ*)‖ becomes sufficiently small.", "Stop when the rate of change of the average squared error per epoch falls within 0.1% to 1%.", "Stop when the network's generalization performance, as measured via cross-validation, has peaked.", "Stop when the number of training epochs exceeds the number of input features in the dataset."], [3],
    "The three valid criteria (from Haykin): small gradient norm, small change in average error per epoch, and peak validation performance (early stopping). The number of input features has nothing to do with convergence.");
  A(2, 18, "Network: input x → hidden φ → output y → error E; the error is backpropagated to update w<sub>1</sub> (input-to-hidden weight) using ∂E/∂w<sub>1</sub> = (∂E/∂y)(∂y/∂v<sup>1</sup>)(∂v<sup>1</sup>/∂w<sub>1</sub>). Which correctly matches each term to its segment and explains why the chain rule is needed?",
    ["∂E/∂y is the input-to-hidden segment; ∂y/∂v<sup>1</sup> is hidden-to-output; ∂v<sup>1</sup>/∂w<sub>1</sub> is output-to-error. The chain rule is needed because w<sub>1</sub> is applied twice in the network.", "∂E/∂y is the output-to-error segment; ∂y/∂v<sup>1</sup> is the hidden-to-output segment; ∂v<sup>1</sup>/∂w<sub>1</sub> is the input-to-hidden segment. The chain rule is needed because w<sub>1</sub> only directly influences v<sup>1</sup> (the hidden layer's net input), and its effect on the final error E must be propagated through every intermediate transformation (v<sup>1</sup> → y → E).", "All three terms represent the same segment (input-to-hidden), since w<sub>1</sub> only exists between the input and hidden layers; the chain rule simply repeats this term three times for numerical stability.", "The chain rule is not actually required here; ∂E/∂w<sub>1</sub> could be computed directly without decomposition, since E is a direct function of w<sub>1</sub>."], [1],
    "Read the product from left to right as walking <b>backwards</b>: error ← output ← hidden ← w<sub>1</sub>. E depends on w<sub>1</sub> only through v<sup>1</sup> and y, so the derivatives multiply.");
  A(2, 19, "Single-layer perceptron, bias input x<sub>0</sub> = −1, bipolar discrete activation. Samples S<sub>1</sub> = [1, −2, 1], S<sub>2</sub> = [1, 1.5, −0.5], S<sub>3</sub> = [−1, 1, 0.5]; labels d = [−1, −1, 1]; initial w = [1, −1, 0, 0.5] (w<sub>0</sub> first); η = 1. Using the perceptron rule, what is w after the first sample S<sub>1</sub>?",
    ["w = [−1, 1, 0, 0.5]", "w = [1, −1, 0, −0.5]", "w = [1, −1, 0, 0.5]", "w = [−1, 1, 0, −0.5]"], [2],
    "Augmented input [−1, 1, −2, 1]. v = 1(−1) + (−1)(1) + 0(−2) + 0.5(1) = −1.5 → y = sgn(−1.5) = −1 = d<sub>1</sub>. Error 0 → <b>no change</b>.");
  A(2, 20, "Same perceptron as above. Continuing for S<sub>2</sub> and S<sub>3</sub>, what is w after one complete epoch?",
    ["w = [1, −1, 0, 0.5]", "w = [1, −1, 0, −0.5]", "w = [−1, 1, 0, 0.5]", "w = [−1, 1, 0, −0.5]"], [0],
    "S<sub>2</sub>: [−1, 1, 1.5, −0.5] → v = −1 − 1 + 0 − 0.25 = −2.25 → y = −1 = d ✓. S<sub>3</sub>: [−1, −1, 1, 0.5] → v = −1 + 1 + 0 + 0.25 = 0.25 → y = +1 = d ✓. All correct → w unchanged = <b>[1, −1, 0, 0.5]</b>.");
  A(2, 21, "In an MLP, for the hidden-layer weight w<sub>11</sub><sup>(1)</sup> (input x<sub>1</sub> → hidden neuron φ<sub>1</sub>), ∂E/∂w<sub>11</sub><sup>(1)</sup> = δ<sub>1</sub><sup>(1)</sup>·x<sub>1</sub>. Find the hidden local gradient δ<sub>1</sub><sup>(1)</sup>.",
    ["δ<sub>1</sub><sup>(1)</sup> = φ′(v<sub>1</sub><sup>(1)</sup>) · Σ<sub>j=1</sub><sup>n</sup> w<sub>j1</sub><sup>(2)</sup> · δ<sub>j</sub><sup>(2)</sup>", "δ<sub>1</sub><sup>(1)</sup> = Σ<sub>j=1</sub><sup>n</sup> w<sub>j1</sub><sup>(2)</sup> · δ<sub>j</sub><sup>(2)</sup>", "δ<sub>1</sub><sup>(1)</sup> = φ′(v<sub>1</sub><sup>(1)</sup>) · Σ<sub>j=1</sub><sup>n</sup> w<sub>1j</sub><sup>(2)</sup> · δ<sub>j</sub><sup>(2)</sup>", "δ<sub>1</sub><sup>(1)</sup> = φ(v<sub>1</sub><sup>(1)</sup>) · Σ<sub>j=1</sub><sup>n</sup> w<sub>j1</sub><sup>(2)</sup> · e<sub>j</sub>"], [0],
    "Hidden local gradient = (own slope φ′) × (sum of the output local gradients, each weighted by the weight that carries hidden neuron 1's signal to output j, i.e. w<sub>j1</sub>). Traps: forgetting φ′, swapping the weight index (w<sub>1j</sub>), using φ instead of φ′, or raw errors e<sub>j</sub> instead of δ<sub>j</sub>.");

  /* ======================= WEEK 3 — assignments ======================= */
  A(3, 1, "Which of the following is a key disadvantage of the sigmoid function compared to tanh?",
    ["It has a steeper gradient near zero", "Its output is not zero-centered", "It cannot be used in deep networks at all", "It has no vanishing gradient problem"], [1],
    "σ ∈ (0, 1) so all outputs are positive → gradients for a layer's weights all share a sign → zig-zag updates. tanh ∈ (−1, 1) is zero-centred and has max slope 1 vs 0.25.");
  A(3, 2, "What is the derivative of tanh(x)?", ["tanh(x)·(1 − tanh(x))", "1 − tanh<sup>2</sup>(x)", "tanh<sup>2</sup>(x) − 1", "1 + tanh<sup>2</sup>(x)"], [1],
    "d/dx tanh x = 1 − tanh²x (maximum 1 at x = 0). Compare sigmoid: σ′ = σ(1 − σ) — the first option is the sigmoid pattern, a trap.");
  A(3, 3, "A neuron's pre-activation is very large (x = 10). What happens to the gradient through both sigmoid and tanh?",
    ["It becomes very large for both", "It approaches zero for both (both saturate)", "It approaches zero for sigmoid only", "It approaches zero for tanh only"], [1],
    "σ′(10) = σ(1 − σ) ≈ 4.5×10<sup>−5</sup>; tanh′(10) = 1 − tanh² ≈ 8×10<sup>−9</sup>. Both curves are flat in their tails → <b>saturation</b>.");
  A(3, 4, "Despite having a stronger gradient near zero, tanh still suffers from which problem?",
    ["Exploding gradients", "Vanishing gradients for large |x|", "Negative outputs causing instability", "Zero-centered bias"], [1], "Saturation at both ends; that is why ReLU became the default for deep networks.");
  A(3, 5, "Why does a very low learning rate (η = 0.0001) still result in high error even after 50 iterations?",
    ["It overshoots the minimum", "It takes such tiny steps that it hasn't reached the minimum yet", "It jumps between two points forever", "The gradient becomes negative"], [1], "Too small η → slow convergence (not divergence). Overshooting/jumping is the too-large case.");
  A(3, 6, "In the ball-rolling-down-a-curve diagram, what does the size of each \"learning step\" (arrow) represent?",
    ["The error value at that point", "The gradient value only", "The product of the learning rate and the gradient", "The number of epochs completed"], [2], "Step Δw = −η∇E → length = η × |gradient|. Steps shrink near the bottom because the slope shrinks.");
  A(3, 7, "If a training loss curve oscillates wildly and even increases at times, what is your first guess about the learning rate?",
    ["It's too low", "It's too high", "It's exactly right", "It has no effect on this behavior"], [1], "Too-large steps jump across the valley (overshoot) and can climb out of it.");
  A(3, 8, "In the momentum update rule ΔW(n) = g(n) + αΔW(n − 1), what does α control?",
    ["The learning rate", "How much the previous update contributes to the current update", "The magnitude of the gradient itself", "The number of iterations before convergence"], [1], "α (0 ≤ α &lt; 1) is the momentum constant — the fraction of the last step carried forward.");
  A(3, 9, "If α is set very close to 1 (e.g., 0.99), what is a likely risk?",
    ["The model converges instantly", "Past gradients are barely retained, so no momentum effect occurs", "The updates can overshoot the minimum since past gradients persist for a long time", "The gradient becomes zero"], [2], "With α = 0.99 the effective memory is ~1/(1 − α) = 100 steps — like a heavy ball that rolls past the minimum and oscillates.");
  A(3, 10, "From the unrolled recurrence ΔW(3) = g(3) + αg(2) + α<sup>2</sup>g(1), what happens to the influence of older gradients as training progresses?",
    ["It stays constant regardless of α", "It grows exponentially", "It decays exponentially, weighted by increasing powers of α", "It disappears completely after one step"], [2], "ΔW(n) = Σ α<sup>n−k</sup> g(k): an exponentially weighted moving sum (|α| &lt; 1).");
  A(3, 11, "Fitting a polynomial y(x, w) = Σ w<sub>j</sub>x<sup>j</sup> to 10 noisy points sampled from sin(2πx) by minimising E(w) = ½Σ{y(x<sub>n</sub>, w) − t<sub>n</sub>}<sup>2</sup>: compare M = 0 (a constant) with M = 9 (10 free parameters). Which statement is correct?",
    ["Both M = 0 and M = 9 achieve E(w*) = 0 on the training data, but M = 0 generalizes better because it's simpler", "M = 0 overfits because it has too few parameters to memorize the data; M = 9 underfits because too many parameters dilute the fit", "Both models have identical training error, but M = 9 has lower test error since more parameters always improve generalization", "M = 0 underfits because a constant cannot capture the oscillation in the data, leading to high bias and high error on both training and test data; M = 9 achieves near-zero training error by exactly interpolating every noisy point, but this fits the noise itself, causing high variance and poor test performance"], [3],
    "Bishop's classic example. 10 points + 10 parameters → the curve passes through every point (training error 0) but wiggles wildly between them. M = 3 is about right.");
  A(3, 12, "Same M = 9 fit compared across λ = 0 (unregularised), ln λ = −18 (moderate) and ln λ = 0 (large). Which statement explains what happens?",
    ["No regularization causes severe oscillation and overfitting since weights are free to grow arbitrarily large to pass through every point; moderate regularization constrains weight magnitudes just enough to recover a smooth curve close to the true sine function; large regularization over-penalizes the weights, forcing them toward zero and causing the fit to flatten into underfitting", "No regularization causes underfitting since the model has too much freedom to generalize; moderate regularization has no effect on weight magnitudes; large regularization is equivalent to increasing M further", "Regularization strength λ only affects training speed, not the shape of the fitted curve or the magnitude of the weights", "Large λ (ln λ = 0) produces the best fit because stronger regularization always improves generalization regardless of the value chosen"], [0],
    "Ẽ(w) = ½Σ(y − t)² + (λ/2)‖w‖². λ trades fit against weight size: too small → overfit, too large → underfit. Choose λ on validation data.");
  A(3, 13, "Your model has almost converged; predictions y are very close to targets d (error ≈ 0.01). Comparing Least Square (LS) and Fourth Power Error (FPE), which suffers severe gradient vanishing in this fine-tuning phase?",
    ["Least Square (LS)", "Fourth Power Error (FPE)", "Both will vanish equally", "Neither will vanish"], [1],
    "LS: E = ½e² → gradient ∝ e = 0.01. FPE: E = ¼e⁴ → gradient ∝ e³ = 10<sup>−6</sup>. The higher power kills small errors' gradients.");
  A(3, 14, "Binary classification with targets d ∈ {−1, 1}; the model outputs y = 2.5 for a sample with d = 1. Which loss is more appropriate if you do not want to penalize the model for being \"too correct\"?",
    ["Least Square (LS)", "Modified Least Square (MLS)", "Fourth Power Error (FPE)", "Both A and B behave the same here."], [1],
    "LS gives (1 − 2.5)² = 2.25 — it punishes a confident, correct answer. <b>MLS</b> only penalises when d·y &lt; 1 (wrong side or inside the margin); for d·y = 2.5 the loss is 0.");
  A(3, 15, "You want weight updates to stop for a sample once it is confidently classified beyond a margin. Which two losses show this zero-loss plateau?",
    ["LS and FPE", "CCE and BCE", "MLS and Risk Sensitive Hinge Loss", "Focal Loss and FPE"], [2],
    "Both are hinge-type: loss = 0 once d·y ≥ margin. Cross-entropy and focal loss keep shrinking but never reach exactly 0; LS/FPE penalise overshooting.");
  A(3, 16, "An object detector sees 99.9 % background and 0.1 % objects. Its output is y = tanh(z) ∈ (−1, 1). How does Focal Loss down-weight the easy background examples?",
    ["By squaring the output probabilities", "By multiplying the loss by a modulating factor ((1 − y)/2)<sup>γ</sup>", "By only calculating loss on the hardest 10% of examples", "By converting the target d to a logarithmic scale"], [1],
    "With p = (1 + y)/2 as the probability of the true class, (1 − p)<sup>γ</sup> = ((1 − y)/2)<sup>γ</sup> → ≈ 0 for confidently correct (easy) samples, ≈ 1 for hard ones. γ = 0 gives plain cross-entropy.");
  A(3, 17, "Sigmoid output layer, confidently wrong (y = 0.99, d = 0). Why is BCE mathematically superior to LS here?",
    ["BCE prevents the sigmoid derivative from collapsing the gradient", "LS cannot be differentiated", "BCE dynamically increases the learning rate", "BCE forces the sigmoid output to be exactly 1 or −1"], [0],
    "LS gradient w.r.t. v: (y − d)·σ′(v) = 0.99 × 0.0099 ≈ 0.0098 — tiny, despite a huge mistake. BCE: ∂E/∂v = y − d = 0.99 — the σ′ cancels.");
  A(3, 18, "For a cost J(θ), which is the standard gradient descent update with learning rate η &gt; 0?",
    ["θ<sub>t+1</sub> = θ<sub>t</sub> + η∇J(θ<sub>t</sub>)", "θ<sub>t+1</sub> = θ<sub>t</sub> − η∇J(θ<sub>t</sub>)", "θ<sub>t+1</sub> = ηθ<sub>t</sub> − ∇J(θ<sub>t</sub>)", "θ<sub>t+1</sub> = θ<sub>t</sub> − (1/η)∇J(θ<sub>t</sub>)"], [1], "Minus sign = descent. A plus sign is gradient ascent.");
  A(3, 19, "Which statements about the learning rate η in gradient descent are correct?",
    ["A very small learning rate may cause slow convergence.", "A very large learning rate may cause the optimization process to overshoot the minimum.", "The learning rate determines the direction of the gradient.", "An excessively large learning rate may cause the cost to oscillate or diverge."], [0, 1, 3], "The gradient alone fixes the direction; η &gt; 0 only scales it.");
  A(3, 20, "Momentum: v<sub>t</sub> = βv<sub>t−1</sub> + ∇J(θ<sub>t</sub>), θ<sub>t+1</sub> = θ<sub>t</sub> − ηv<sub>t</sub>. With v<sub>t−1</sub> = 2, β = 0.9, ∇J(θ<sub>t</sub>) = 3, η = 0.1 and θ<sub>t</sub> = 5, find θ<sub>t+1</sub>.",
    ["4.52", "4.70", "5.48", "5.30"], [0],
    "v<sub>t</sub> = 0.9 × 2 + 3 = 4.8. θ<sub>t+1</sub> = 5 − 0.1 × 4.8 = <b>4.52</b>. (4.70 = plain GD without momentum; 5.48 = wrong sign.)");
  A(3, 21, "Which are potential advantages of using momentum in gradient descent?",
    ["It can accelerate movement in directions where gradients consistently point in the same direction.", "It can reduce oscillations in directions where gradients change rapidly.", "It guarantees convergence to the global minimum for every non-convex cost function.", "It uses information from previous gradients when computing the current update."], [0, 1, 3], "Nothing guarantees a global minimum on non-convex surfaces.");
  A(3, 22, "Cost J(w) = w<sup>2</sup> − 6w + 10, dJ/dw = 2w − 6. At w = 5, which direction should steepest descent move?",
    ["Move towards larger values of w, because dJ/dw|<sub>w=5</sub> = 4", "Move towards smaller values of w, because dJ/dw|<sub>w=5</sub> = 4", "Do not move, because the derivative is zero.", "The direction cannot be determined from the derivative."], [1],
    "2(5) − 6 = 4 &gt; 0 → the function rises to the right → step left (smaller w), towards the minimum at w = 3.");

  /* ======================= WEEK 4 — assignments ======================= */
  A(4, 1, "The matrix [[1, 2], [3, 4], [5, 6]] is a rank-2 tensor. What is the minimum number of indices needed to pinpoint the number 5, and what does this say about why it is \"rank-2\"?",
    ["You need 6 indices, one for each element in the matrix, rank equals the total number of values stored.", "You need 1 index, since 5 appears only once, rank equals the number of unique values.", "You need 2 indices (e.g., \"row 2, column 0\"), rank equals the number of independent axes you must specify to locate any single value, not the size or number of elements.", "You need 3 indices, since the matrix has 3 rows, rank equals the number of rows in the structure."], [2],
    "Tensor rank (order / ndim) = number of axes. Do not confuse with the <i>matrix rank</i> of linear algebra (number of independent columns).");
  A(4, 2, "A rank-4 tensor has shape (3, 2, 4, 5) — 120 elements. If the shape becomes (5, 2, 4, 3) by swapping the sizes of axis 0 and axis 3, what does this tell you?",
    ["The tensor now has more total elements, since axis 0 grew from 3 to 5.", "The tensor is now rank-5, since one of its axis sizes changed.", "Swapping axis sizes like this is not possible without changing the total number of elements.", "Still rank-4 with 120 elements, only which axis holds which size has changed."], [3], "Rank = number of axes (4); size = product of the shape = 5·2·4·3 = 120. This is a transpose/permute.");
  A(4, 3, "A line fitted to four points has errors (+8, −8, +8, −8). Compare the raw sum Σ(y<sub>i</sub> − ŷ<sub>i</sub>) with the sum of squared errors Σ(y<sub>i</sub> − ŷ<sub>i</sub>)<sup>2</sup>.",
    ["Both measures give the same result here, since the errors are symmetric, so it doesn't matter which one you use for this data.", "The raw sum equals 0, falsely suggesting a perfect fit, while the sum of squared errors equals 256, correctly revealing that every single point is actually off by a substantial amount.", "The raw sum equals 256, correctly showing the total error, while the sum of squared errors equals 0, incorrectly suggesting a perfect fit.", "The raw sum is always larger than the sum of squared errors, since squaring shrinks large numbers."], [1], "8 − 8 + 8 − 8 = 0, but 4 × 64 = 256. Squaring stops positive and negative errors cancelling.");
  A(4, 4, "Line A has errors (+1, +1, +1, +1); Line B has (+10, −10, +1, −1). Using the sum of squared errors, which is better and what does this reveal?",
    ["Line A is better, since squared errors always favor small, consistent errors over having any large outliers, even if the raw sum of errors is similar.", "Line B is better, since two of its errors are very close to zero, and least squares only cares about the smallest individual error.", "Both lines are judged equally, since the raw (unsquared) sum of errors is the same for both (+4 vs 0, so actually different), squaring doesn't change the ranking.", "Line B is better, since squared errors reward having a mix of positive and negative errors that could cancel out."], [0], "SSE(A) = 4, SSE(B) = 100 + 100 + 1 + 1 = 202. Squaring punishes big errors heavily (and makes least squares sensitive to outliers).");
  A(4, 5, "A radial basis function primarily depends on:", ["The direction of the input vector.", "The distance between the input and a center point", "The number of output classes", "The order of the input features"], [1], "φ(x) = φ(‖x − c‖) — radially symmetric about the centre c.");
  A(4, 6, "Which statements about radial basis functions are correct?",
    ["Their output usually depends on the distance from a center.", "They can be used for interpolation and function approximation.", "Gaussian functions are commonly used as radial basis functions.", "Their output always increases as the input moves farther from the center."], [0, 1, 2], "The Gaussian RBF decreases with distance (peak 1 at the centre). Some RBFs (multiquadric) increase, so \"always increases\" is false.");

  /* ======================= WEEK 5 — assignments ======================= */
  A(5, 1, "In the Hubel and Wiesel experiment, which statements can be said to be true?",
    ["V1 cells are spatially invariant", "Stimulus for objects that are vertically placed is highest", "There is a hierarchy in V2 cells", "The proposed structure is closely related to modern CNN's architectures"], [0, 2, 3],
    "Hubel &amp; Wiesel found orientation-selective cells in the visual cortex organised in a hierarchy (simple → complex cells), which inspired the Neocognitron and CNNs. Responses depend on the preferred orientation of each cell — not specifically on vertical objects.",
    { note: "Official key also accepts <b>\"V1 cells are spatially invariant\"</b> — you lost 0.33 here by not ticking it. Strictly, simple cells are position-specific and complex cells (also in V1) tolerate position shifts; the course treats V1 as showing spatial invariance. Tick it if this question repeats." });
  A(5, 2, "Which statements regarding the Neocognitron architecture are true?",
    ["Architecture was made to extract features that are spatially invariant", "It demonstrated the spatial invariance of hierarchical structures", "It had alternating S, and C layers for feature extraction", "S cells give spatial invariance, and C cells extract local features"], [0, 1, 2],
    "Fukushima (1980): <b>S-cells</b> (simple) extract local features; <b>C-cells</b> (complex) pool them to give shift tolerance. The last option swaps the roles.");
  A(5, 3, "Which statements are true for hierarchical spatial networks?",
    ["Local features of an image are detected in later stages of network", "Better understanding of local features reduces need for larger data for training", "Complex features are also referred to as global features", "Complex features are robust features in a network"], [1, 2, 3],
    "Local features (edges) are detected <i>early</i>; later layers combine them into complex/global, more robust features.",
    { note: "Official key includes <b>\"Better understanding of local features reduces need for larger data\"</b> — you missed it (0.67). Reason: shared, well-learned local detectors are reused everywhere, so fewer examples are needed." });
  A(5, 4, "A 32 × 32 input is convolved with a 5 × 5 kernel. Which statements are correct?",
    ["With stride 1 and no padding, the output spatial size is 28 × 28.", "With stride 1 and padding 2, the output spatial size is 32 × 32.", "Increasing the stride generally reduces the spatial dimensions of the output feature map.", "Padding always decreases the spatial dimensions of the output feature map."], [0, 1, 2],
    "Output = (W − K + 2P)/S + 1. (32 − 5)/1 + 1 = 28; (32 − 5 + 4)/1 + 1 = 32. Padding <i>increases</i> output size.");
  A(5, 5, "An RGB image of size 64 × 64 × 3 goes into a conv layer with 16 filters of spatial size 3 × 3. Which statements are correct?",
    ["Each filter must have dimensions 3 × 3 × 3.", "Each filter produces one output feature map.", "Assuming stride 1 and appropriate padding to preserve spatial dimensions, the output has size 64 × 64 × 16.", "Each input channel is convolved independently and produces a separate final output channel without combining information across channels."], [0, 1, 2],
    "A filter always spans the full input depth (3) and <b>sums over channels</b> → one map per filter → 16 maps. (Independent per-channel filtering is depthwise convolution, not standard.)");
  A(5, 6, "Which statements about convolution and pooling are correct?",
    ["A discrete convolution operation with fixed kernel weights can be represented as multiplication by a structured matrix.", "Convolution with a fixed kernel satisfies linearity with respect to its input.", "Max-pooling is a linear operation because it reduces the spatial dimensions of the feature map.", "Average pooling is linear with respect to the values within the pooling region."], [0, 1, 3],
    "Convolution = multiplication by a (doubly) Toeplitz matrix → linear. Average = fixed weights 1/n → linear. max(a + b) ≠ max(a) + max(b) → max-pooling is nonlinear; shrinking size has nothing to do with linearity.");
  A(5, 7, "A CNN is trained to recognize handwritten digits. Which statements correctly describe the role of convolutional layers?",
    ["They can learn local patterns such as edges, curves, and corners.", "The same convolutional filter is applied at different spatial locations in an image.", "Every neuron in a convolutional layer must be connected to every pixel in the input image.", "Deeper convolutional layers can combine simple patterns into more complex digit-specific features."], [0, 1, 3], "Local connectivity + weight sharing + hierarchy. Full connectivity is what conv layers avoid.");
  A(5, 8, "A small handwritten digit shifts by a few pixels left or right. Which property of pooling helps a CNN remain less sensitive to this shift?",
    ["Increasing the number of trainable parameters", "Summarizing activations within a local neighborhood", "Assigning a separate weight to every image pixel", "Converting the image into a one-dimensional vector"], [1], "The max (or average) of a window barely changes when the feature moves inside the window → local translation invariance. Pooling has no parameters.");
  A(5, 9, "Why are nonlinear activation functions such as ReLU used between convolutional layers?",
    ["They allow the network to represent nonlinear relationships.", "Without nonlinear activations, stacking several linear layers would still behave like a linear transformation.", "ReLU guarantees that a CNN will never overfit.", "Nonlinear activations enable deep networks to learn more complex decision boundaries."], [0, 1, 3], "W<sub>2</sub>(W<sub>1</sub>x) = (W<sub>2</sub>W<sub>1</sub>)x — still one linear map. Nothing guarantees no overfitting.");
  A(5, 10, "Why are CNNs generally more suitable than fully connected networks for image recognition?",
    ["CNNs completely eliminate the need for training data.", "CNNs exploit spatial locality and share parameters across image locations.", "CNNs always contain fewer layers than fully connected networks.", "CNNs do not require activation functions."], [1], "Locality + weight sharing → far fewer parameters and built-in translation equivariance.");
  A(5, 11, "A CNN pretrained on a large general image dataset is transferred to a smaller digit-recognition dataset. Why might this be useful?",
    ["Early convolutional layers may already contain useful low-level feature detectors.", "It may reduce the amount of task-specific training required.", "Pretraining guarantees perfect performance on the new dataset.", "Features learned from one visual dataset can sometimes be useful for another visual task."], [0, 1, 3], "Nothing guarantees perfection — negative transfer can even happen when domains differ a lot.");
  A(5, 12, "In transfer learning, what is the main difference between feature extraction and fine-tuning?",
    ["Feature extraction uses only augmented images, whereas fine-tuning uses original images.", "Feature extraction keeps pretrained layers fixed, while fine-tuning updates some or all pretrained parameters.", "Feature extraction requires no classifier, whereas fine-tuning always removes the classifier.", "Fine-tuning does not use pretrained weights."], [1], "Feature extraction: freeze the backbone, train only a new head. Fine-tuning: also unfreeze (some) backbone layers, usually with a small learning rate.");
  A(5, 13, "A model recognizes handwritten digits. Which considerations are important when selecting data-augmentation operations?",
    ["The transformation should normally preserve the correct class label.", "Small translations may be appropriate because digit position can vary.", "Every geometrically possible transformation should automatically be used.", "The validity of an augmentation depends on the semantics of the task."], [0, 1, 3], "Rotating a 6 by 180° makes a 9 — so not every transform is safe. (For top-down aerial images, any rotation <i>is</i> safe.)");
  A(5, 14, "Vertically flipping an image of a particular symbol can change its meaning. What is the main problem with using vertical flipping as augmentation?",
    ["It increases image resolution.", "It may create a training image whose assigned label is no longer correct.", "It prevents convolution from being performed.", "It makes the CNN a linear model."], [1], "Label noise: the flipped image keeps the old label but now shows a different symbol.");
  A(5, 15, "A CNN achieves very high training accuracy but substantially lower test accuracy. Appropriate data augmentation may help because:",
    ["It exposes the network to additional variations of the training examples.", "It can discourage the network from memorizing exact training-image configurations.", "It can improve generalization when the transformations reflect realistic variations.", "It guarantees that training accuracy and test accuracy will become identical."], [0, 1, 2], "Augmentation is a regulariser against overfitting; it guarantees nothing.");

  /* ======================= WEEK 6 — assignments ======================= */
  A(6, 1, "Which of the following best describes the layer flow of LeNet-5?",
    ["Alternating convolution and subsampling layers, followed by fully-connected layers", "A stack of convolution layers with a single pooling layer at the very end", "Parallel convolution branches whose outputs are concatenated", "Convolution layers connected by residual shortcuts", "Fully-connected layers followed by convolution layers"], [0],
    "LeNet-5: C1 → S2 → C3 → S4 → C5 → F6 → output. Parallel branches = Inception; shortcuts = ResNet.");
  A(6, 2, "Which of the following describe AlexNet's architecture?",
    ["Five convolutional layers followed by three fully-connected layers", "A large 11x11 filter with stride 4 in the first convolution layer", "Overlapping max-pooling windows", "Dropout applied in the fully-connected layers", "Fully convolutional with no fully-connected layers"], [0, 1, 2, 3],
    "Also: ReLU activations, local response normalisation, data augmentation, ~60 M parameters, trained on two GTX 580 GPUs. Pooling 3×3 with stride 2 = overlapping.");
  A(6, 3, "Why was AlexNet split across two GPUs?",
    ["To allow each GPU to train on a different dataset", "Because a single GPU of the time lacked the memory to hold the whole model", "To run the convolutional and fully-connected halves in parallel", "To average predictions from two independently trained networks"], [1],
    "Each GTX 580 had 3 GB — not enough for the network and activations, so the kernels were split between two GPUs, communicating only at certain layers.", { k: "worked" });
  A(6, 4, "Which describe ZFNet's changes to AlexNet and the reasoning behind them?",
    ["It used a deconvnet visualization to inspect what intermediate layers respond to", "The visualization showed the first layer producing aliased, dead, high-frequency filters", "The first conv layer was changed from 11x11/stride-4 to 7x7/stride-2 to retain more information", "It replaced all convolutions with 1x1 convolutions", "It removed the pooling layers entirely"], [0, 1, 2],
    "Zeiler &amp; Fergus (2013) visualised features with a deconvolutional network and fixed the first layer's aliasing with a smaller kernel and stride.");
  A(6, 5, "VGG replaces a single 7x7 convolution with three stacked 3x3 convolutions (C input and C output channels, stride 1). Which hold?",
    ["The effective receptive field is unchanged at 7x7", "The parameter count drops from 49C<sup>2</sup> to 27C<sup>2</sup>", "The block becomes three layers deep instead of one", "It reduces the spatial resolution faster", "It increases the parameter count"], [0, 1, 2],
    "Receptive field 3 → 5 → 7. Parameters: one 7×7 = 7·7·C·C = 49C²; three 3×3 = 3·9·C² = 27C². Three ReLUs instead of one → more nonlinearity.");
  A(6, 6, "Which statement best captures the data flow inside a GoogLeNet Inception module?",
    ["The input passes sequentially through 1x1, then 3x3, then 5x5 convolutions", "The input is split channel-wise, with each branch handling a different slice", "The input feeds several parallel branches whose outputs are concatenated along depth", "The input feeds several parallel branches whose outputs are summed element-wise"], [2],
    "Branches: 1×1; 1×1→3×3; 1×1→5×5; 3×3 max-pool→1×1. Same spatial size, outputs stacked along channels. (Summing is ResNet's style.)");
  A(6, 7, "What do the 1x1 convolutions inside the Inception module accomplish?",
    ["Channel-wise dimensionality reduction before the expensive 3x3 and 5x5 branches", "Reducing the computational cost of the module", "Cross-channel feature mixing", "Enlarging the spatial receptive field", "Downsampling the feature map spatially"], [0, 1, 2],
    "A 1×1 kernel sees one pixel position → cannot enlarge the receptive field or downsample (stride 1); it mixes channels and can shrink their number (bottleneck).");
  A(6, 8, "GoogLeNet has ~5M parameters while VGG-16 has ~138M, despite being deeper. What is the single largest reason?",
    ["GoogLeNet shares weights across all Inception modules", "GoogLeNet uses global average pooling instead of large fully-connected layers", "GoogLeNet uses fewer layers than VGG", "VGG uses 7x7 convolutions throughout the network", "GoogLeNet quantizes its weights during training"], [1],
    "VGG-16's first FC layer alone is 7·7·512·4096 ≈ 103 M parameters. Global average pooling has none.");
  A(6, 9, "Which are true of the ResNet residual block, H(x) = F(x) + x?",
    ["It was motivated by the degradation problem, where deeper plain networks showed higher training error", "The degradation problem was an overfitting problem", "The identity mapping is easy to learn, since it only requires F(x) = 0", "The shortcut adds no extra parameters when the dimensions match", "The ReLU activation is applied after the shortcut addition, not before it"], [0, 2, 3, 4],
    "Degradation shows up as higher <b>training</b> error, so it is an optimisation problem, not overfitting (which shows high test error with low training error).");
  A(6, 10, "Which are true of the ResNet bottleneck block used in ResNet-50/101/152?",
    ["It has the ordering 1x1 → 3x3 → 1x1", "The first 1x1 reduces channel depth; the last 1x1 restores it", "The 3x3 convolution operates on a reduced number of channels, keeping cost low", "It is also used in ResNet-18 and ResNet-34", "A 1x1 projection shortcut is used when the shortcut's dimensions do not match"], [0, 1, 2, 4],
    "ResNet-18/34 use the <b>basic block</b> (two 3×3 convs). Example: 256 → 64 (1×1) → 64 (3×3) → 256 (1×1).");
  A(6, 11, "During training, as earlier layers' parameters change, the distribution of activations feeding later layers keeps shifting from batch to batch, even though the training data never changes. What is this phenomenon and the standard fix?",
    ["Dataset covariate shift; fixed via data augmentation", "Internal covariate shift; fixed via Batch Normalization", "Label shift; fixed via loss re-weighting", "Vanishing gradients; fixed via ReLU activations"], [1], "Ioffe &amp; Szegedy (2015).");
  A(6, 12, "You apply Z-score normalization z = (x − μ)/σ. A colleague claims it \"changes the shape of the data's distribution — e.g., turns a skewed distribution into a symmetric one\". True?",
    ["Yes — normalization forces all features onto the same scale, which inherently symmetrizes any distribution", "Yes — dividing by the standard deviation compresses outliers more than typical values, reshaping the distribution's tails", "No — Z-normalization has no effect at all on the data, it only changes variable names for documentation purposes", "No — Z-normalization only shifts and rescales the data linearly; skewness, kurtosis, and overall shape remain exactly the same"], [3], "A linear map (subtract, divide by a constant) cannot change the shape; to un-skew you need a nonlinear transform such as log.");
  A(6, 13, "Activations have shape (Batch, Channel, Height, Width). A colleague claims \"Instance Normalization computes the same mean and variance as Batch Normalization — only the name differs.\" True?",
    ["Yes — both methods normalize using statistics computed across the entire batch, so the resulting normalized values are identical regardless of which name is used", "No — Instance Normalization computes mean and variance per-sample, per-channel (across only Height and Width), while Batch Normalization computes them per-channel across the entire batch (across Batch, Height, and Width together)", "Yes — \"Instance\" and \"Batch\" simply refer to two different terms for the same normalization operation used in different research papers", "No — Instance Normalization normalizes across the Channel dimension only, ignoring spatial and batch dimensions entirely"], [1],
    "BN: over (N, H, W) per channel. LN: over (C, H, W) per sample. IN: over (H, W) per sample and channel. GN: over groups of channels and (H, W) per sample. See the normalisation demo on the Week 6 page.");
  A(6, 14, "In neural style transfer, replacing Batch Normalization with Instance Normalization in the generator gave better stylisation. Given that IN strips each channel's per-image contrast and intensity statistics, why does this help?",
    ["Faster training only", "Removes image-specific contrast, style becomes learnable", "Increases model capacity", "Fixes vanishing gradients"], [1], "Ulyanov et al. (2016): per-image statistics carry the content image's contrast; removing them lets the network impose the target style.");

  /* ======================= WEEK 7 — assignments ======================= */
  A(7, 1, "In the evolution RNN → LSTM → Attention, LSTM adds a cell state (memory highway) and forget/input/output gates. Despite this, what limitation does LSTM still carry that motivates Attention?",
    ["LSTMs lack a memory component entirely", "LSTMs suffer from vanishing gradients only", "LSTMs cannot store any long-term information", "LSTMs are still fundamentally sequential"], [3],
    "Step t needs h<sub>t−1</sub>, so time steps cannot be processed in parallel, and distant information must pass through many steps. Attention connects every position directly (and Transformers parallelise it).");
  A(7, 2, "A Memory Neural Network stores patterns as fixed, content-addressable associative memory but has no notion of temporal order (cannot tell \"A before B\" from \"B before A\"). What design change addresses this, and which architecture introduces it?",
    ["Adding more stored patterns to increase memory capacity, still within a Memory Neural Network", "Introducing gates that selectively forget or retain stored patterns, as in LSTM", "Processing inputs one step at a time while updating an internal hidden state, as in RNN", "Computing a weighted combination over all positions simultaneously, as in Attention"], [2],
    "Order comes from <b>recurrence</b>: h<sub>t</sub> depends on h<sub>t−1</sub>, so the state encodes what came before. Gates (LSTM) refine this later.");
  A(7, 3, "In the Memory Neuron Network, a memory neuron keeps m<sub>t</sub> = α·h<sub>t</sub> + (1 − α)·m<sub>t−1</sub>. What role does α play?",
    ["It determines the number of network-neurons in each layer of the architecture", "It controls the trade-off between how much weight is given to the current input's contribution versus the accumulated memory from all previous timesteps", "It is a learnable weight applied only to the connections between network-neurons, unrelated to memory", "It determines whether the neuron is classified as a network-neuron or a memory-neuron in the diagram"], [1],
    "Exponential moving average: α → 1 = forget quickly (mostly current), α → 0 = long memory. Unrolled: m<sub>t</sub> = α Σ (1 − α)<sup>k</sup> h<sub>t−k</sub>.");
  A(7, 4, "The memory neuron uses a single fixed (or globally learned) scalar α shared across all timesteps; LSTM replaces it with input-dependent forget/input gates computed fresh at every step. What fundamental limitation of fixed α does LSTM gating address?",
    ["Cannot handle variable-length sequences", "Decay rate is content-blind, not input-dependent", "Produces no output, only a memory state", "Requires multiple memory cells to function"], [1], "With a fixed α the network forgets at the same rate whether the input is important or not. A gate f<sub>t</sub> = σ(W[h<sub>t−1</sub>, x<sub>t</sub>]) decides per step and per input.");
  A(7, 5, "In an MNN trained by gradient descent, the output memory neuron's activation is v<sup>3</sup>(k) = α(k)·h(k − 1) + (1 − α(k))·v<sup>3</sup>(k − 1). A feedforward weight β updates simply as β(k + 1) = β(k) − ηe(k)v(k), but α's update has an extra term (h(k − 1) − v(k − 1)). Why?",
    ["α controls a recurrent blend between the current and previous memory state at the output memory neuron, so its gradient must account for how the memory value one step earlier was itself shaped by α — a dependency β doesn't have", "β is an output-layer weight and therefore skips gradient computation entirely, unlike α", "The extra term is simply a regularization penalty added to prevent α from growing too large during training", "α is a probability and must be constrained between 0 and 1, so the extra term acts as a normalization factor"], [0],
    "∂v/∂α = h(k − 1) − v(k − 1): α weights the <i>difference</i> between the new value and the stored memory, a recurrent dependence β lacks.");
  A(7, 6, "In a standard RNN, s<sub>t</sub> = tanh(Ux<sub>t</sub> + Ws<sub>t−1</sub>), and U, V, W are reused at every step whether the sequence has 5 steps or 500. Why is this parameter-sharing a deliberate design choice?",
    ["It reduces the total number of parameters compared to giving each time step its own weights, but this comes at the cost of the model being unable to generalize to sequences of different lengths than it was trained on", "It allows the same learned transformation to be applied regardless of the sequence's length, meaning the model can process sequences of any length using a fixed number of parameters, and any pattern learned at one position in the sequence can be recognized regardless of where it occurs", "It is necessary purely for computational efficiency during training, since using different weights at each time step would make backpropagation mathematically impossible to compute", "It ensures that the hidden state s<sub>t</sub> at every time step is numerically identical, since applying the same weights to different inputs always produces the same output"], [1], "Weight sharing across time = what convolution does across space.");
  A(7, 7, "In a standard RNN with W reused at every step, training on a sequence of length T requires Backpropagation Through Time (BPTT), summing gradient contributions across all steps. Why sum across all previous steps instead of computing just the current step's gradient?",
    ["Because W is reused at every time step, its value at time t was also responsible for producing s<sub>t−1</sub>, s<sub>t−2</sub>, and so on, so changing W retroactively affects every past hidden state that fed into the current one, and each of these must contribute to the total gradient", "Because RNNs require more training data than feedforward networks, so the extra summation compensates for the smaller effective sample size at each individual time step", "Because the softmax output layer y<sub>t</sub> = softmax(Vs<sub>t</sub>) is nonlinear, and nonlinear functions always require summing gradients across multiple points to remain numerically stable", "Because the hidden state s<sub>t</sub> is bounded between −1 and 1 by the tanh function, and this bounded range forces the gradient computation to be distributed across several time steps rather than concentrated in one"], [0],
    "∂L/∂W = Σ<sub>k</sub> (∂L/∂s<sub>t</sub>)(∂s<sub>t</sub>/∂s<sub>k</sub>)(∂s<sub>k</sub>/∂W). The product ∂s<sub>t</sub>/∂s<sub>k</sub> of many Jacobians is also where vanishing/exploding gradients come from.");
  A(7, 8, "The LSTM cell state is the horizontal line at the top of the diagram through which information flows almost unchanged, modified only via gate interactions. Why is it better than the vanilla RNN hidden state s<sub>t</sub> for preserving information over long gaps?",
    ["The cell state uses a different activation function (linear/identity-like updates via addition) rather than repeatedly passing through a squashing nonlinearity like tanh at every step, so information isn't forced through a compressive transformation each time", "The cell state has a larger dimensionality than the hidden state, so it can simply store more information in absolute terms", "The cell state is recomputed from scratch at every time step using only the current input, making it independent of past errors", "The cell state bypasses backpropagation entirely, so no gradient ever flows through it"], [0],
    "C<sub>t</sub> = f<sub>t</sub> ⊙ C<sub>t−1</sub> + i<sub>t</sub> ⊙ C̃<sub>t</sub>: additive. With f ≈ 1, ∂C<sub>t</sub>/∂C<sub>t−1</sub> ≈ 1 — the \"constant error carousel\".");
  A(7, 9, "LSTMs update the cell state in two steps: the forget gate decides what to discard from C<sub>t−1</sub>; the input gate and candidate C̃<sub>t</sub> (tanh) decide what to add. Why two separate gates rather than one?",
    ["Doubles trainable parameters, always improving capacity", "Retain and add are independent decisions; one gate can't represent both", "A single gate is mathematically impossible to implement", "Required purely for symmetry with the output gate"], [1],
    "Sometimes you must keep the old memory <i>and</i> write new information (f ≈ 1, i ≈ 1); a single gate g with (1 − g) mixing would force a trade-off. (GRU does couple them, as a simplification.)");
  A(7, 10, "In attention-based encoder-decoders, the decoder computes a different context vector at every output step t: c<sub>t</sub> = Σ<sub>i</sub> α<sub>t,i</sub>h<sub>i</sub>, with alignment weights from a small feed-forward network recomputed each step. A vanilla encoder-decoder compresses the whole source into one fixed-length vector. What limitation does attention address?",
    ["Attention exists to reduce total parameter count", "Fixed-length vector creates an information bottleneck that worsens with source length", "Vanilla approach cannot use a bidirectional encoder", "Vanilla context vectors are not differentiable"], [1], "Bahdanau, Cho &amp; Bengio (2015): BLEU of the fixed-vector model collapsed on long sentences; attention lets each output step look back at all encoder states.");

  /* ======================= WEEK 8 — assignments ======================= */
  A(8, 1, "In a shared-feature-extractor detection pipeline, one CNN backbone feeds two heads: classification (cross-entropy) and localization/regression (box (x<sub>c</sub>, y<sub>c</sub>, w, h) via smooth L<sub>1</sub>). Why is sharing one feature extractor a deliberate design choice?",
    ["It is required because classification and localization must always use identical loss functions, and separate backbones would produce mismatched losses", "The features useful for recognizing what an object is (edges, textures, shape) substantially overlap with the features useful for determining where it is, so a single backbone can serve both tasks — avoiding the computational cost of running two full CNNs on the same image and letting both tasks benefit from jointly learned representations", "Separate backbones would make the network's output resolution too high for practical use, so sharing forces the resolution down to a manageable size", "Sharing is only done to reduce the total number of output classes the network needs to support"], [1], "The two heads even use <i>different</i> losses (CE and smooth L1) — they are summed into one multi-task loss.");
  A(8, 2, "NMS on one car: Box A (confidence 0.95, covers the whole car), Box B (0.80, IoU with A = 0.7), Box C (0.75, IoU with A = 0.2, mostly just the side mirror). With IoU threshold 0.5, which boxes remain?",
    ["Box A and Box C remain; Box B is suppressed because its IoU with Box A (0.7) exceeds the 0.5 threshold, while Box C's IoU with Box A (0.2) is below threshold, so it is not considered a duplicate of Box A", "Only Box A remains, since NMS always keeps just the single highest-confidence box regardless of overlap with others", "Box A and Box B remain, since both have high confidence scores above 0.75, and only Box C is discarded for having the lowest confidence", "All three boxes are discarded, since NMS requires unanimous agreement between all overlapping boxes before any can be kept"], [0],
    "Greedy NMS: keep the top box, delete boxes with IoU &gt; threshold, repeat. C survives — a false positive NMS cannot remove because it overlaps too little. Step through it in the NMS demo.");
  A(8, 3, "A two-stage detector is Detector = f<sub>refine</sub> ∘ f<sub>extract</sub> ∘ f<sub>propose</sub>: f<sub>propose</sub> outputs a few hundred to a few thousand class-agnostic regions, and f<sub>refine</sub> does class-specific classification and box regression per region. Why is f<sub>propose</sub> independent of class identity?",
    ["Class-agnostic proposals always use fewer parameters", "Defers expensive class-specific decisions to a small, pre-filtered region set", "f<sub>refine</sub> cannot process class information at all", "Function composition requires shrinking output spaces at each step"], [1], "Stage 1 only asks \"is there an object?\" (cheap, shared by all classes); stage 2 spends effort on ~2000 candidates instead of every window × every class.");
  A(8, 4, "Original R-CNN: (1) Selective Search → ~2,000 proposals, (2) warp each to 227 × 227 and pass through a full CNN, (3) class-specific SVMs, (4) box regression. What is the primary computational bottleneck later architectures (Fast R-CNN) eliminate?",
    ["Selective Search itself is a learned neural network component, and R-CNN's bottleneck is that this network cannot be trained end-to-end with the rest of the pipeline", "The SVM classifiers require the entire training dataset to be held in memory simultaneously, making R-CNN's memory footprint the primary bottleneck rather than its runtime", "The CNN forward pass is run independently for each of the ~2,000 region proposals per image, meaning the same underlying image content gets redundantly re-processed through convolutional layers thousands of times", "Bounding-box regression in R-CNN requires a second full pass of Selective Search after classification, doubling the region-proposal computation"], [2], "Fast R-CNN runs the CNN once per image and crops each region from the shared feature map (RoI pooling). Selective Search is not learned.");
  A(8, 5, "R-CNN trains in 6 separate stages (proposals; ImageNet pre-training; fine-tuning with softmax + warped inputs; caching features; class-specific SVMs; per-class box regressors at IoU ≥ 0.6 vs ≥ 0.5 for fine-tuning). Fast R-CNN uses one multi-task loss (softmax + smooth L<sub>1</sub>) on RoI-pooled features from one shared CNN pass. Most direct reason it no longer needs the SVM stage?",
    ["Softmax is inherently more accurate than SVMs", "ROI pooling keeps CNN, classifier, and regressor in one differentiable path, so classification gradients update the shared features", "SVMs cannot run on GPU hardware", "R-CNN's SVMs require a separate labeled dataset"], [1], "End-to-end training: the classifier's loss now trains the features too, so a separately trained SVM on frozen features adds nothing.");
  A(8, 6, "In Faster R-CNN's RPN, each feature-map location has k anchors (k = 9: 3 scales × 3 aspect ratios). Anchors with IoU &gt; 0.7 (or highest IoU) are positive, IoU &lt; 0.3 negative, and 0.3–0.7 are ignored. Why exclude these \"neutral\" anchors?",
    ["Neutral anchors are computationally expensive to process", "A fixed anchor budget forces neutral anchors to be dropped", "Neutral anchors are excluded only from the classification loss", "Forcing a confident label on a genuinely ambiguous anchor injects noisy, contradictory supervision"], [3], "An anchor half-covering an object is neither clearly object nor clearly background.");
  A(8, 7, "A region proposal projected on the feature map is 15 × 15; RoI Pooling divides it into a 7 × 7 grid (sub-window ≈ 15/7 = 2.14, not an integer). What does standard RoI Pooling do, and what problem does it cause?",
    ["It pads the region with zeros to make 15 evenly divisible by 7, introducing no misalignment", "It rounds subwindow boundaries to the nearest integer (quantizes), causing small spatial misalignment between the pooled features and the true region boundaries", "It rejects any region proposal whose size isn't evenly divisible by the grid size", "It interpolates feature values continuously, so no misalignment ever occurs"], [1], "Rounding twice (proposal → feature grid, then bins) shifts features by up to a feature-map cell (= 16 image pixels at stride 16). <b>RoI Align</b> (Mask R-CNN) uses bilinear sampling instead — see the demo.");
  A(8, 8, "Faster R-CNN's 4-step alternating training: (1) train RPN from ImageNet weights; (2) train a separate Fast R-CNN on step-1 proposals; (3) re-initialise RPN from the step-2 detector, freeze shared conv layers, fine-tune RPN-only layers; (4) keep shared layers frozen, fine-tune Fast R-CNN-only layers. Why freeze the shared conv layers in steps 3 and 4?",
    ["Freezing speeds up training by reducing gradient computations", "Backpropagation cannot flow through RPN's anchor mechanism", "Freezing is a generic regularization technique, unrelated to sharing", "Freezing prevents RPN and the detector from pulling the shared features in conflicting directions, keeping both networks converged on one common feature representation"], [3], "Goal: one shared backbone usable by both heads.");
  A(8, 9, "In the comparison diagram, the link between \"Region CNN features\" and the classifier/regressor is \"Independent\" in R-CNN but \"Joint\" in Fast and Faster R-CNN; the link between the image and \"Region proposal\" + \"Deep CNN\" is \"Independent\" in R-CNN and Fast R-CNN but replaced by an RPN fed from the CNN's own features in Faster R-CNN. What does each transition fix?",
    ["R-CNN → Fast R-CNN fixes the disconnected classifier; Fast R-CNN → Faster R-CNN fixes the disconnected proposal generator", "Both transitions fix the same disconnected-gradient problem, just at different layers", "R-CNN → Fast R-CNN fixes the proposal bottleneck; Fast R-CNN → Faster R-CNN fixes the classifier bottleneck", "Neither transition relates to gradient flow; both just reduce proposal count"], [0], "Remember the chain: R-CNN (everything separate) → Fast (joint classifier + regressor) → Faster (proposals learned too, ~real-time).");
  A(8, 10, "In YOLO (v1) the image is an S × S grid; each cell predicts B boxes with confidence Pr(Object) × IoU<sup>truth</sup><sub>pred</sub>. Two objects' centres fall in the same cell. What limitation does this create and how do anchor boxes help?",
    ["YOLO can only assign one class prediction per grid cell, so without anchor boxes, only one of the two overlapping objects can be correctly detected; anchor boxes let each grid cell predict multiple boxes of different shapes, each responsible for a different object", "YOLO cannot process images where two objects appear simultaneously at all, regardless of grid cell; anchor boxes fix this by increasing the total grid resolution", "The confidence score formula becomes mathematically undefined when two objects share a grid cell, and anchor boxes fix this by redefining IoU", "This limitation only affects inference speed, not detection accuracy; anchor boxes are purely a runtime optimization unrelated to multi-object grid cells"], [0], "YOLOv1 output: S × S × (B·5 + C) — one set of C class probabilities per cell. YOLOv2 moved class prediction to each anchor.");
  A(8, 11, "DETR's decoder takes a fixed, learned set of N \"object queries\" (content-independent slots); each, through cross-attention with image features, becomes one prediction. Unlike Faster R-CNN anchors or YOLO grid cells, what is the key implication of learned, content-independent queries?",
    ["Queries cannot represent spatial information at all, making DETR blind to location", "Each query must learn its own specialization purely from data, rather than having it hand-designed via anchor scales or grid position", "Queries make DETR incapable of detecting more than one object per image", "Queries are mathematically equivalent to anchors, just renamed"], [1], "DETR also uses Hungarian (bipartite) matching between predictions and ground truth, so it needs no NMS.");
  A(8, 12, "An aerial detector is trained only on clear-weather, normal-brightness imagery and tested on images that are brightened, darkened, blurred or with snow — without ever fine-tuning on or seeing labelled examples of these conditions. What makes this domain generalization rather than domain adaptation?",
    ["DG requires labeled target-domain data during training; adaptation requires none", "Model trained only on source domain, must handle unseen target conditions with zero access during training", "DG and adaptation are the same problem, differing only in dataset used", "DG applies only to classification, not detection tasks"], [1], "Domain <b>adaptation</b> uses target-domain data (often unlabelled) during training; domain <b>generalization</b> never sees the target.");

  /* ======================= WEEK 9 — assignments ======================= */
  A(9, 1, "A 5 × 5 feature map passes through a transposed convolution with a 2 × 2 kernel and stride = 2, no padding and no output padding. What is the output spatial size?",
    ["8 × 8", "9 × 9", "10 × 10", "11 × 11"], [2], "Output = (H − 1)·S − 2P + K = (5 − 1)·2 − 0 + 2 = <b>10</b>. (With K = S it exactly doubles the size.)");
  A(9, 2, "In a Fully Convolutional Network (FCN) for semantic segmentation, what is the primary purpose of replacing the fully connected layers of a traditional CNN with convolutional layers?",
    ["To reduce the number of training images required", "To preserve spatial information and produce a spatial prediction for each pixel", "To eliminate the need for convolutional layers", "To convert a segmentation problem into an image classification problem"], [1], "FC layers flatten away the layout; 1×1 convolutions keep a coarse score map that is then upsampled. Also allows any input size.");
  A(9, 3, "A segmentation model is evaluated on 4 classes. Confusion matrix (rows = ground truth, columns = predicted): C1: 50 10 5 0; C2: 8 40 2 0; C3: 4 6 45 5; C4: 0 2 8 35. What is the mean IoU (mIoU)?",
    ["0.681", "0.694", "0.712", "0.735"], [2],
    "Method: IoU<sub>c</sub> = TP / (row sum + column sum − TP). Row sums 65, 50, 60, 45; column sums 62, 58, 60, 40. IoU = 50/77 = 0.649, 40/68 = 0.588, 45/75 = 0.600, 35/50 = 0.700.",
    { note: "<b>Warning — key mismatch.</b> The official key is <b>0.712</b> (you chose 0.681 and lost the mark). But the four IoUs above average to <b>0.634</b>, which is not among the options; pixel accuracy is 170/220 = 0.773. The key seems inconsistent with the matrix. If this exact question repeats, choose 0.712; for any other matrix use the method above (practise in the mIoU calculator on the Week 9 page)." });
  A(9, 4, "SegNet uses max-pooling indices from the encoder in its decoder. What is the main intuition behind using these indices?",
    ["They help restore spatial locations while the decoder performs upsampling.", "They help recover feature magnitudes that were removed during pooling.", "They allow the decoder to avoid convolutional operations during segmentation.", "They preserve the locations of the strongest activations during spatial upsampling."], [3],
    "The decoder puts each value back at the exact position where the max came from (sparse \"unpooling\"), then convolves to densify. Only indices are stored — memory-efficient compared with U-Net's full feature maps.",
    { note: "Only the last option was accepted. The first one sounds similar, but the key wants the precise idea: the <i>locations of the maximum activations</i>." });
  A(9, 5, "In U-Net, what is the main purpose of the skip connections between encoder and decoder?",
    ["They allow the decoder to use high-level semantic features from deeper layers", "They allow the encoder to perform additional pooling before decoding begins", "They reduce the number of feature channels while preserving classification accuracy", "They combine detailed spatial features from the encoder with decoder features during upsampling."], [3], "Encoder maps at the same resolution are <b>concatenated</b> to the decoder maps — the high-resolution \"where\" meets the deep \"what\".");
  A(9, 6, "In U-Net, skips concatenate encoder maps with decoder maps at matching resolutions. If all skips are removed (same depth) on a task with very small objects, what is the main consequence?",
    ["No effect, bottleneck encodes all pixel info losslessly", "Rough object presence survives, but precise boundaries don't, downsampling irreversibly loses spatial detail, hurting small objects most; skip connections restore it.", "Only large objects are affected, small objects are smaller than the bottleneck's receptive field", "Skip connections mainly cut decoder parameters, so removing them mainly slows training."], [1], "A 4-pixel object at 1/16 resolution occupies a fraction of a cell; upsampling cannot recover what pooling threw away.");
  A(9, 7, "A CNN's final feature map is 13 × 13 × 256. An SPP layer uses pyramid levels 1 × 1, 2 × 2 and 4 × 4, max-pooling each of the 256 maps. Which statement is correct?",
    ["The SPP output has dimensions 13 × 13 × 256, because SPP preserves the spatial dimensions of the final convolutional feature map.", "The SPP output contains 21 × 256 = 5376 values, and this output size remains fixed even if the spatial dimensions of the incoming feature map change.", "The SPP output contains (1 + 2 + 4) × 256 = 1792 values, because the number of bins is determined by the sum of the pyramid dimensions.", "SPP eliminates the need for convolutional layers operating at different scales because a single 1 × 1 pooling bin captures all local and global spatial information."], [1], "Bins = 1² + 2² + 4² = 21 (count squares, not sides). Fixed length → any input size can feed an FC layer (He et al., SPP-net).");
  A(9, 8, "In DeepLabV3, the Atrous Spatial Pyramid Pooling (ASPP) module uses parallel atrous convolutions with different dilation rates. What is the primary reason for multiple rates?",
    ["To reduce the number of feature channels while preserving spatial resolution", "To capture contextual information at multiple spatial scales without substantially reducing the feature-map resolution", "To replace the backbone CNN by performing all feature extraction using dilated convolutions", "To ensure that every pixel in the feature map is processed using the same effective receptive field."], [1], "Dilation r enlarges a 3×3 kernel's reach to (2r + 1) without extra parameters or pooling. Rates 6, 12, 18 (+ 1×1 and image pooling) = multi-scale context.");
  A(9, 9, "A building-segmentation model (DeepMAO) combines an undercomplete U-Net branch with an overcomplete branch that progressively increases spatial resolution. Which statement BEST explains the purpose of the overcomplete branch?",
    ["It increases the receptive field and captures semantic information while reducing the spatial resolution of feature representations.", "It replaces the encoder and decoder structure by extracting all features through progressively upsampled representations alone.", "It duplicates the U-Net branch at higher resolution primarily to increase model parameters and improve overall network representation capacity", "It preserves fine structural information through higher-resolution representations, complementing semantic features learned by the undercomplete branch"], [3], "Overcomplete = upsample between conv blocks → receptive field shrinks → focuses on fine edges and small structures (building boundaries). The first option describes the undercomplete branch.");
  A(9, 10, "In an overcomplete network (upsampling between conv blocks, factor 2), the receptive field of conv block i is (½)<sup>2(i−1)</sup> × k × k; an undercomplete network (pooling, factor 2) has 2<sup>2(i−1)</sup> × k × k. What does comparing them reveal?",
    ["They're reciprocals — as depth increases, overcomplete RF shrinks toward zero while undercomplete RF grows unbounded; upsampling and pooling produce opposite trends.", "They converge to the same value at large i, since both networks eventually cover the full input regardless of upsampling or pooling.", "They're unrelated, since RF growth depends only on kernel size k, not on upsampling vs. pooling.", "Overcomplete RF grows just as fast as undercomplete RF, since both exponents share magnitude 2(i − 1), differing only by a sign that cancels."], [0], "2<sup>2(i−1)</sup> × (½)<sup>2(i−1)</sup> = 1. At i = 3 with k = 3: undercomplete 16 × 9 = 144 vs overcomplete 9/16 ≈ 0.56 (in input-pixel area units).");
  A(9, 11, "Standard per-pixel classification assigns each pixel an independent class label. Mask classification predicts a fixed set of binary masks, each with a single class prediction. What is the key structural distinction, and why does mask classification \"disentangle\" segmentation?",
    ["Mask classification predicts pixels independently just like per-pixel classification, differing only in the loss function used to train each pixel's label.", "Per-pixel classification couples partitioning and classification into one dense per-pixel decision; mask classification separates these — a mask handles partitioning, one class label handles each mask.", "Mask classification eliminates classification entirely, since binary masks alone are sufficient to solve segmentation without predicting any class labels at all.", "Per-pixel and mask classification are mathematically identical formulations, differing only in whether output is visualized as pixels or as masks."], [1], "\"Where are the regions?\" (masks) and \"what is each region?\" (one label per mask) become separate outputs.");
  A(9, 12, "MaskFormer computes N probability–mask pairs using (1) a pixel-level module (per-pixel embeddings), (2) a transformer module (decoder layers), (3) a segmentation module. Since it outputs a fixed N pairs regardless of image content, how does it unify semantic and instance segmentation?",
    ["Since N is fixed and semantic classes vary per dataset, MaskFormer cannot handle semantic segmentation, working only for instance tasks with bounded object counts", "MaskFormer solves only semantic segmentation; instance segmentation still needs a separate per-pixel classification head appended afterward to the output", "The transformer module's decoder layers activate only for instance segmentation, and are skipped entirely when running semantic segmentation tasks.", "Since both tasks reduce to predicting class-labeled masks, MaskFormer predicts one mask per class for semantic, one per object for instance, same N-pair format covers both"], [3], "Unused pairs predict \"no object\" (∅). Mask2Former extends the same idea to panoptic segmentation.");
  A(9, 13, "SAM (Segment Anything v1) must output a valid mask even for ambiguous prompts (a point on a shirt could mean the shirt, the person, or the torso). Its decoder predicts multiple masks (typically 3) with confidence scores instead of one. Why not just average the masks into one output?",
    ["Averaging is avoided purely for computational efficiency, since picking one mask via argmax is cheaper than any averaging operation across the three candidates", "Averaging distinct valid masks (e.g., shirt vs. whole person) would blend mutually exclusive interpretations into one incoherent region, since these represent different objects, not noisy estimates of one.", "SAM cannot output multiple masks per single prompt; the \"3 masks\" language refers to batching 3 separate prompts together, not resolving prompt ambiguity", "Averaging binary segmentation masks is mathematically undefined, since pixel-wise binary values cannot be combined in floating-point arithmetic at all."], [1], "Averaging is right for noisy estimates of the same thing, wrong for different valid answers (whole / part / subpart). During training only the best of the 3 masks gets the loss.");

  /* ======================= WEEK 10 — assignments ======================= */
  A(10, 1, "In knowledge distillation the student is trained on a \"softened\" teacher output: the teacher's logits are divided by a temperature T &gt; 1 before the softmax. Why does a higher T help the student learn more than the teacher's hard (one-hot-like) predictions?",
    ["A higher T sharpens the teacher's output distribution, forcing the student to focus only on the single most confident class prediction at each training step", "A higher T softens the distribution, revealing relative probabilities across incorrect classes too, which encodes richer inter-class similarity structure than a hard label provides.", "A higher T removes all information from the teacher's output entirely, making the student rely solely on the ground-truth hard labels during training.", "A higher T only affects the student's own logits during inference, leaving the teacher's soft-label training targets completely unaffected by the change."], [1], "Hinton et al. (2015) — \"dark knowledge\": a cat image scoring 10 % \"dog\" and 0.01 % \"car\" tells the student that cats look like dogs. Try the temperature slider on the Week 10 page.");
  A(10, 2, "Distillation minimises Loss = D<sub>KL</sub>(P<sub>T</sub> ‖ P<sub>S</sub>) = Σ<sub>i</sub> P<sub>T</sub>(i) log(P<sub>T</sub>(i)/P<sub>S</sub>(i)). KL is asymmetric. Why is the teacher placed first?",
    ["D<sub>KL</sub>(P<sub>T</sub> ‖ P<sub>S</sub>) heavily penalizes the student for assigning low probability to classes the teacher considers plausible, forcing the student to cover all of the teacher's probability mass rather than collapsing onto only its most confident mode.", "D<sub>KL</sub>(P<sub>S</sub> ‖ P<sub>T</sub>) would be mathematically undefined during training, since the student's distribution changes at every gradient step while the teacher's stays fixed throughout.", "The choice of direction is arbitrary and has no effect on training dynamics, since both orderings converge to the same optimal student parameters given enough training steps.", "D<sub>KL</sub>(P<sub>T</sub> ‖ P<sub>S</sub>) is used only because it is cheaper to compute than the reverse direction, with no relationship to what the student actually learns to represent."], [0], "Forward KL (reference first) is <b>mass-covering</b>; reverse KL is mode-seeking. Minimising forward KL in the student's parameters is the same as minimising cross-entropy with soft targets.");
  A(10, 3, "With D<sub>KL</sub>(P<sub>T</sub> ‖ P<sub>S</sub>) = Σ P<sub>T</sub>(i) log(P<sub>T</sub>(i)/P<sub>S</sub>(i)), suppose the teacher gives a small but non-zero P<sub>T</sub>(i) &gt; 0 to some class while the student gives P<sub>S</sub>(i) ≈ 0. What happens to the loss and what does it imply?",
    ["The term P<sub>T</sub>(i) log(P<sub>T</sub>(i)/P<sub>S</sub>(i)) blows up toward a very large value as P<sub>S</sub>(i) → 0, so the loss strongly penalizes the student for placing near-zero probability wherever the teacher places any nonzero probability, discouraging mode-collapse.", "The term shrinks toward zero as P<sub>S</sub>(i) → 0, since a smaller student probability always reduces the magnitude of any log-ratio term regardless of the teacher's assigned probability value.", "The loss becomes exactly zero in this case, since KL divergence is only sensitive to classes where both P<sub>T</sub>(i) and P<sub>S</sub>(i) are simultaneously large, not where either one is small.", "This scenario has no effect on the gradient, since KL divergence only depends on the argmax class of each distribution, ignoring the specific probability values assigned elsewhere."], [0],
    "log(P<sub>T</sub>/P<sub>S</sub>) → +∞ as P<sub>S</sub> → 0. (The reverse case P<sub>T</sub> = 0 contributes nothing, since 0·log 0 = 0.)", { k: "worked" });
  A(10, 4, "Contrastive Predictive Coding (CPC) uses InfoNCE: ℒ = −log[exp(sim(z, z<sup>+</sup>)/τ) / Σ<sub>i</sub> exp(sim(z, z<sub>i</sub>)/τ)], predicting future <i>latent</i> representations rather than raw future data. Why use a contrastive loss over embeddings instead of reconstructing raw future inputs?",
    ["Raw prediction forces modeling high-entropy, low-level detail irrelevant to shared structure; contrastive prediction only needs to distinguish the true future from negatives, capturing high-level shared information.", "Predicting raw future inputs is mathematically impossible for high-dimensional signals, so contrastive prediction is used purely out of computational necessity.", "Contrastive prediction and raw reconstruction optimize the same objective, differing only in which loss is more convenient to implement.", "Contrastive prediction is used only to cut GPU memory usage, since raw reconstruction needs larger intermediate activations."], [0], "InfoNCE is a softmax cross-entropy where the \"correct class\" is the positive among K candidates; minimising it maximises a lower bound on mutual information.");
  A(10, 5, "SimCLR uses a base encoder f(·) followed by a small projection head g(·) where the contrastive loss is applied; g(·) is discarded after pretraining. Why include a separate projection head?",
    ["g(·) exists purely to reduce dimensionality for computational efficiency, with no effect on the quality of f(·)'s learned representations.", "Applying the loss directly on f(·) would force it to discard task-useful information (e.g., color, rotation); routing loss through g(·) lets f(·) stay more general, since only g(·)'s output is forced invariant.", "g(·) and f(·) are functionally interchangeable, so which one is discarded after training has no measurable effect on downstream performance.", "g(·) is included only to satisfy a fixed input-dimension requirement of the loss function, unrelated to what f(·) learns."], [1], "Chen et al. (2020): linear evaluation on h = f(x) is &gt;10 % better than on z = g(h).");
  A(10, 6, "Pixel-level contrastive learning: for an anchor pixel, distinguish a similar (positive) pixel from dissimilar (negative) pixels in a projected embedding space, using semantic similarities among labelled pixels across the whole dataset — not just one image. Standard per-pixel cross-entropy compares each pixel only with its own label. What does pixel-level contrastive learning add?",
    ["It pulls same-class pixels together (even across images) and pushes different-class pixels apart, using cross-pixel/cross-image relationships that per-pixel CE ignores", "It removes the need for class labels entirely, since pixel-to-pixel contrast alone determines semantic categories without supervision", "It only compares pixels within the same image, making it identical to per-pixel CE loss at finer spatial resolution", "It penalizes pixels only in isolation, with no dependence on any other pixel's embedding or label"], [0], "Wang et al. (2021), \"Exploring cross-image pixel contrast\". It is supervised (uses labels) and complements CE.", { k: "worked" });
  A(10, 7, "In multi-spectral systems viewing the same object through different modalities, low frequencies carry shared information while high frequencies carry each modality's distinct features. Why does exploiting the correlation between low and high frequencies help constrain a solution (e.g., multi-modal fusion or cross-modal reconstruction)?",
    ["Since low frequencies are shared but high frequencies are modality-specific, knowing the low-frequency content restricts the plausible range of high frequencies, rather than searching all completions independently per modality.", "Low and high frequencies are always statistically independent in any imaging system, so leveraging their correlation provides no actual constraint on the solution space at all.", "High frequencies alone are sufficient to reconstruct any modality, making the shared low-frequency information entirely redundant for constraining the solution", "Correlating low and high frequencies only helps compress data for storage efficiency, with no bearing on solving multi-modal reconstruction or fusion tasks."], [0], "A prior: the shared coarse structure narrows down which fine details are plausible.");
  A(10, 8, "A pruning method removes \"inhibited\" channels — those with the smallest magnitude (e.g. smallest BatchNorm γ or channel weight norm), assumed to have the least impact. A colleague says pruning them should always leave accuracy unchanged, regardless of how many are pruned. Why is this flawed?",
    ["Smallest → least impact is only a heuristic; it's imperfect, and pruning too many channels removes capacity the remaining ones relied on, eventually hurting accuracy.", "Pruning always improves accuracy regardless of amount removed, since inhibited channels are provably pure noise with zero information", "Channel magnitude perfectly measures true contribution, so pruning by magnitude guarantees zero accuracy loss at any ratio", "Reliance on remaining channels has no bearing on accuracy, since remaining channels operate fully independently of pruned ones"], [0], "In practice: prune → fine-tune → repeat, and watch the accuracy-vs-sparsity curve bend down.");
  A(10, 9, "Continual learning has a stability–plasticity trade-off. A colleague says: \"Catastrophic forgetting comes from overwriting old weights, so just freeze all weights after task 1 — zero forgetting, and the network still learns new tasks normally.\" Why is this flawed?",
    ["Freezing weights maximizes stability but removes plasticity entirely, so the network can no longer learn new tasks at all.", "Freezing weights affects neither property, since stability and plasticity depend only on the loss function chosen", "Freezing weights increases plasticity, since a frozen network can represent infinitely many new tasks without interference", "Forgetting only occurs when weights are frozen, so unfreezing all weights guarantees perfect retention automatically"], [0], "Real methods balance both: regularise important weights (EWC), replay old samples, or add new capacity per task.", { k: "worked" });

  /* ======================= WEEK 11 — assignments (not yet graded) ======================= */
  var S11 = { k: "submitted" };
  A(11, 1, "Which set of characteristics best distinguishes Reinforcement Learning from supervised and unsupervised learning?",
    ["Labelled examples, immediate feedback, and training on a fixed dataset", "Hidden-pattern discovery, no reward signal, and i.i.d. training data", "No supervisor (only a reward), delayed feedback, and actions that shape future data", "A correct target output for every input, supplied by a supervisor"], [2], "The agent's actions change which states (data) it sees next, and rewards may arrive many steps later (credit assignment).", S11);
  A(11, 2, "In the return G<sub>t</sub> = R<sub>t+1</sub> + γR<sub>t+2</sub> + γ<sup>2</sup>R<sub>t+3</sub> + …, what is the effect of setting γ close to 0?",
    ["The agent becomes far-sighted and weighs distant rewards heavily", "The infinite sum of rewards is guaranteed to diverge to infinity", "All future rewards are weighted equally with the immediate reward", "The agent becomes myopic and cares almost only about immediate reward"], [3], "γ → 0: G ≈ R<sub>t+1</sub>. γ → 1: far-sighted. γ &lt; 1 keeps the infinite sum finite (≤ R<sub>max</sub>/(1 − γ)).", S11);
  A(11, 3, "The Markov property, central to a Markov Decision Process, states that:",
    ["The next state depends only on the current state and action, not the past", "The next state depends on the entire history of states and actions", "The transition probabilities must be known to the agent in advance", "The reward at each step must be deterministic for the process to hold"], [0], "P(s<sub>t+1</sub> | s<sub>t</sub>, a<sub>t</sub>, history) = P(s<sub>t+1</sub> | s<sub>t</sub>, a<sub>t</sub>). Model-free methods (Q-learning) do not need the transition probabilities.", S11);
  A(11, 4, "Which statement correctly describes the difference between Q-learning and SARSA?",
    ["Q-learning is on-policy, while SARSA is off-policy and needs a model", "Q-learning's target uses the greedy max over next actions, while SARSA's uses the action actually taken next", "SARSA uses a neural network, whereas Q-learning uses a lookup table", "Q-learning requires the transition model; SARSA learns without one"], [1], "Q-learning: r + γ max<sub>a′</sub> Q(s′, a′) — off-policy. SARSA: r + γ Q(s′, a′) with the a′ actually chosen (ε-greedy) — on-policy. Both are model-free.", S11);
  A(11, 5, "Why does tabular RL (e.g., a Q-table) fail for a real drone, motivating function approximation?",
    ["Continuous, high-dimensional states cannot be enumerated in a finite table, forcing generalization", "Lookup tables are simply too slow to read from during real-time flight", "Q-tables are unable to store the negative reward values used for obstacle cells", "Tables can only represent on-policy algorithms such as SARSA"], [0], "Position, velocity, attitude, camera images → infinitely many states. A neural network Q(s, a; θ) generalises between similar states (DQN).", S11);
  A(11, 6, "In DQN, what are the two key techniques that stabilize training?",
    ["Dropout and batch normalization, which prevent the network from overfitting", "A higher learning rate with gradient clipping to accelerate convergence", "Double sampling and importance weighting to remove on-policy bias", "Experience replay and a target network, which stabilize an otherwise unstable bootstrap"], [3], "Replay buffer breaks the correlation of consecutive samples; a slowly updated target network Q<sup>−</sup> stops the target moving with every step (Mnih et al., 2015).", S11);
  A(11, 7, "How does an Actor-Critic method combine value-based and policy-based RL?",
    ["The Actor estimates the value function while the Critic chooses the actions", "Two independent policies vote, and the majority action is executed each step", "The Actor selects actions while the Critic evaluates them by estimating a value/Q function", "Both policy and value are dropped in favour of a learned environment model"], [2], "Actor = policy π<sub>θ</sub>(a|s); Critic = V or Q estimate whose TD error tells the actor whether the action was better than expected. DDPG, A2C, PPO and SAC are actor-critic methods.", S11);
  A(11, 8, "When transferring a drone policy trained in simulation to real hardware, what is \"domain randomization\"?",
    ["Randomly reinitializing network weights between successive training runs", "Randomizing sim parameters like mass, wind, and sensor noise to force a robust policy", "Selecting random actions at deployment to keep exploring on the hardware", "Shuffling the replay buffer at random before every gradient update"], [1], "If the policy works across many randomised simulators, the real world looks like just another variation (closing the sim-to-real gap).", S11);
  A(11, 9, "A Q-learning agent uses α = 0.5 and γ = 0.9. Q(s, a) = 2.0, reward r = 1.0, next-state values Q(s′, ·) = {5.0, 3.0, 4.0}. Using Q(s, a) ← Q(s, a) + α[r + γ·max<sub>a′</sub> Q(s′, a′) − Q(s, a)], what is the updated Q(s, a)?",
    ["4.75", "5.50", "3.75", "2.85"], [2], "Target = 1 + 0.9 × 5 = 5.5; TD error = 5.5 − 2 = 3.5; Q = 2 + 0.5 × 3.5 = <b>3.75</b>. (2.85 is what SARSA gives if the next action taken had Q = 3.)", S11);
  A(11, 10, "An ε-greedy policy with ε = 0.2 acts in a state with 4 actions. Exploration (probability ε) picks uniformly among all 4 actions. What is the probability that the single greedy (highest-Q) action is chosen?",
    ["0.85", "0.80", "0.25", "0.20"], [0], "P = (1 − ε) + ε/|A| = 0.8 + 0.2/4 = <b>0.85</b> — the greedy action can also be picked while exploring.", S11);
  A(11, 11, "Why is GAN training often described as a minimax game rather than a conventional supervised optimization problem?",
    ["Both networks minimize the same fixed reconstruction loss", "The generator and discriminator have competing objectives, with improvements in one network affecting the optimization problem faced by the other", "GANs require the training dataset to contain both images and segmentation masks", "The generator and discriminator never exchange gradient information during training"], [1], "min<sub>G</sub> max<sub>D</sub> V(D, G) = E[log D(x)] + E[log(1 − D(G(z)))]. The generator's gradients flow through D.", S11);
  A(11, 12, "A generator produces sharp, realistic-looking images, but there is very little diversity among the samples. Which evaluation concern does this illustrate?",
    ["High visual quality alone does not guarantee that the generator has captured the diversity of the real-data distribution", "Sharp images always indicate that the discriminator has underfit the dataset", "A GAN should generate exactly one representative image for each class", "Image diversity is irrelevant as long as individual samples appear realistic"], [0], "Metrics such as FID (and precision/recall for GANs) measure both quality and coverage.", S11);
  A(11, 13, "In a Conditional GAN (cGAN), how does generation differ from a standard unconditional GAN?",
    ["The generator no longer receives a latent vector", "The generator and usually the discriminator receive additional conditioning information, such as a class label, allowing control over the type of sample generated", "The discriminator is removed entirely and replaced by a classifier", "The generator is trained only using a reconstruction loss"], [1], "G(z, y) and D(x, y). Pix2Pix conditions on a whole input image.", S11);
  A(11, 14, "Why can alternating updates of the generator and discriminator make GAN training unstable?",
    ["The target each network is optimizing against changes as the other network is updated, producing a non-stationary optimization problem", "The discriminator cannot be trained using gradient descent", "The generator's weights are randomly reinitialized whenever the discriminator is updated", "GANs require the two networks to have exactly the same architecture and number of parameters"], [0], "Like chasing a moving target — can oscillate instead of converging.", S11);
  A(11, 15, "In a Wasserstein GAN (WGAN), what is one main motivation for replacing the original divergence-based objective with the Wasserstein distance?",
    ["To eliminate the need for a generator", "To provide a smoother and more informative training signal, particularly when the real and generated distributions have little overlap", "To force every generated image to correspond to a paired real image", "To make the discriminator output only binary values of exactly 0 or 1"], [1], "With non-overlapping distributions the JS divergence is a constant (log 2) → no gradient; the Earth-Mover distance still shrinks as they move closer. The critic outputs a real-valued score.", S11);
  A(11, 16, "During GAN training the generator starts producing only a few visually convincing types of samples, even though the real data has many categories and variations. What is this called?",
    ["Gradient clipping", "Mode collapse", "Feature normalization", "Latent regularization"], [1], "Many z map to the same few outputs (modes).", S11);
  A(11, 17, "In the original GAN formulation, what is the discriminator primarily trained to do?",
    ["Reconstruct the input image from a compressed latent representation", "Predict the latent vector used by the generator", "Distinguish between real samples from the training distribution and fake samples produced by the generator", "Minimize the pixel-wise distance between real and generated samples"], [2], "A binary real/fake classifier.", S11);
  A(11, 18, "Suppose the discriminator becomes almost perfect very early in GAN training. Why can this be a problem for the generator?",
    ["The discriminator automatically deletes generated samples that are classified as fake", "The generator may receive very weak or uninformative gradients, making it difficult to improve", "The latent vectors become identical after every discriminator update", "The generator is forced to memorize the real training dataset exactly"], [1], "log(1 − D(G(z))) saturates when D(G(z)) ≈ 0 → vanishing gradient. Fix: the non-saturating loss −log D(G(z)), or WGAN.", S11);
  A(11, 19, "What is the role of the latent vector z in a standard GAN?",
    ["It contains the ground-truth label of the image being generated", "It acts as a random input from which the generator produces different samples", "It stores the discriminator's classification error", "It contains a compressed version of a corresponding real image"], [1], "z ~ N(0, I) or uniform; different z → different samples.", S11);
  A(11, 20, "At the theoretical equilibrium of the original GAN (sufficient capacity, ideal optimization), what should happen?",
    ["The generator distribution matches the real-data distribution, and the discriminator outputs approximately 0.5 for both real and generated samples", "The discriminator outputs 1 for all real samples and 0 for all generated samples", "The generator reproduces every training image exactly", "The discriminator loss becomes zero while the generator loss continues increasing"], [0], "D*(x) = p<sub>data</sub>/(p<sub>data</sub> + p<sub>g</sub>) = ½ when p<sub>g</sub> = p<sub>data</sub>. See the D* demo on the Week 11 page.", S11);

  /* ======================= WEEK 12 — assignment (unanswered; worked out) ======================= */
  var M12 = { k: "mine" };
  A(12, 1, "How is the \"neutralization\" of an intruder drone formally defined in the perimeter defense model?",
    ["The defender completely disables the intruder's communication signal.", "The defender and intruder come into a small ball of radius R, allowing the defender to capture it.", "The defender blocks the intruder's camera vision for more than 10 seconds", "The intruder is forced to land by a localized EMP."], [1], "Capture is geometric: the distance between defender and intruder falls below a capture radius R before the intruder reaches the perimeter.", M12);
  A(12, 2, "In spatial-temporal task allocation, what two parameters are calculated to determine where and when an intruder will arrive?",
    ["Altitude and wind speed", "GPS coordinates and battery life", "Location (p<sub>i</sub>) and time (t<sub>i</sub>) based on velocity and heading information", "Sensor range and maneuverability rate"], [2], "From the intruder's position, speed and heading: arrival point p<sub>i</sub> on the perimeter and arrival time t<sub>i</sub> (= distance/speed). Try it in the perimeter-defence demo.", M12);
  A(12, 3, "When formulating the cost for the task-assignment optimization, what cost is assigned if a task is \"infeasible\" (the drone cannot reach the location on time)?",
    ["Zero", "Infinity", "It is assigned to a reserve drone automatically", "It is given a negative weight"], [1], "An infinite (very large) cost guarantees that a minimum-cost assignment never picks that defender–intruder pair. Zero or negative would make it the most attractive choice.", M12);
  A(12, 4, "What is the specific input provided to the Multitask Assignment Spiking Neural Network?",
    ["A 3D map of the environment", "Raw RGB camera frames", "A spike train representing the presence of intruders and their proportional distance/time to the perimeter", "The optimization cost function matrix"], [2], "SNNs work on spikes: the information (an intruder is present, and how soon it arrives) is encoded in spike timing/rate.", M12);
  A(12, 5, "Compared to standard optimization-based solutions, what is a primary advantage of the learning-based spiking neural network for task allocation?",
    ["It operates without using any battery power.", "It is scalable to different territory shapes and more drones without needing to be retrained.", "It guarantees zero collisions even if sensors fail.", "It can capture multiple intruders simultaneously with one drone."], [1], "Optimisation must be re-solved (and can grow combinatorially) for every new configuration; the trained SNN generalises and is fast and low-power on neuromorphic hardware.", M12);
  A(12, 6, "Which combination of intrinsic sensors is traditionally used alongside satellite information to estimate a drone's velocity and attitude?",
    ["LiDAR and 4D Radar", "RGB Camera and Thermal Sensor", "Accelerometers and Gyroscopes (IMU)", "Pitot tube and flow sensor"], [2], "GNSS + IMU fusion (usually a Kalman filter). Cameras and LiDAR are extrinsic (exteroceptive) sensors.", M12);
  A(12, 7, "In what scenario is Visual SLAM highly likely to fail due to a lack of texture?",
    ["Flying indoors in a cluttered office", "Flying over a sea or flying over a desert", "Flying through a dense forest", "Flying in a highly illuminated urban environment"], [1], "Visual SLAM tracks distinctive feature points; uniform water or sand gives none (and water moves).", M12);
  A(12, 8, "What is listed as the biggest problem for LiDAR SLAM?",
    ["Dealing with suspended particles like fog and smoke.", "Scale ambiguity when objects are close.", "Navigating in featureless areas like open fields or long tunnels and empty halls.", "Low angular resolution"], [2], "LiDAR SLAM matches geometry; in open fields or uniform corridors every scan looks the same along the travel direction (degeneracy). Scale ambiguity is a monocular-camera problem.", M12);
  A(12, 9, "How do data-driven soft sensors (like the proposed \"Acceleration Network\") attempt to solve long-term IMU drift?",
    ["By constantly pinging nearby cell towers.", "By using unbiased data to train a network that rectifies current IMU data, giving an output with the bias removed.", "By switching off the IMU and relying solely on the visual camera", "By applying a constant mathematical filter based on factory settings."], [1], "Bias integrated twice grows as ½bt² in position. A network trained on reference (unbiased) data learns to correct the raw IMU stream.", M12);
  A(12, 10, "How is the future of \"end-to-end navigation\" in autonomous systems described?",
    ["Relying purely on pre-computed static maps downloaded before the flight.", "Processing sensory input through separate, isolated blocks for perception, mapping, and obstacle avoidance.", "Directly converting sensor inputs (like images or LiDAR) into safe trajectory and control commands using integrated AI models.", "Eliminating all extrinsic sensors and flying purely on IMU data."], [2], "The second option describes today's modular pipeline, which end-to-end learning aims to replace.", M12);
})();
